def _install_poe_native_compat(poe_module: Any) -> Any:
    required = ("update_settings", "start_message", "query", "default_chat")
    if all(hasattr(poe_module, attr) for attr in required):
        return poe_module

    class _PoeNativeCompatProxy:
        def __init__(self, wrapped: Any) -> None:
            self._wrapped = wrapped
            self.query = getattr(
                wrapped,
                "query",
                types.SimpleNamespace(text=" ".join(sys.argv[1:]), attachments=[]),
            )
            self.default_chat = getattr(wrapped, "default_chat", [])

        def __getattr__(self, name: str) -> Any:
            return getattr(self._wrapped, name)

        def update_settings(self, settings: Any) -> Any:
            fn = getattr(self._wrapped, "update_settings", None)
            return fn(settings) if fn else None

        def start_message(self) -> Any:
            fn = getattr(self._wrapped, "start_message", None)
            return fn() if fn else _CompatStartMessage()

    return _PoeNativeCompatProxy(poe_module)


