def _now_beijing() -> datetime:
    return _RUNTIME_CLOCK.get() or datetime.now(BEIJING)


@contextmanager
def runtime_clock(clock: datetime):
    if clock.tzinfo is None:
        raise ValueError("运行时覆盖时钟必须带时区")
    token = _RUNTIME_CLOCK.set(clock.astimezone(BEIJING))
    try:
        yield
    finally:
        _RUNTIME_CLOCK.reset(token)


@contextmanager
def historical_replay(day: date | None):
    """Select an explicit completed session for audited catch-up only."""

    token = _HISTORICAL_REPLAY_DAY.set(day)
    try:
        yield
    finally:
        _HISTORICAL_REPLAY_DAY.reset(token)


