def beijing_today() -> date:
    return _now_beijing().date()


def normalize_query(text: str) -> str:
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", text or "")).strip()


_CN_NUM = {
    "零": 0,
    "一": 1,
    "二": 2,
    "两": 2,
    "三": 3,
    "四": 4,
    "五": 5,
    "六": 6,
    "七": 7,
    "八": 8,
    "九": 9,
    "十": 10,
    "半": 0.5,
}


def _number(value: str) -> float:
    if value.isdigit():
        return float(value)
    if value in _CN_NUM:
        return float(_CN_NUM[value])
    if value.count("百") > 1 or value.count("十") > 1 or "半" in value:
        raise ValueError(f"无法识别数字: {value}")
    total = 0
    remainder = value
    if "百" in remainder:
        left, remainder = remainder.split("百", 1)
        if left not in _CN_NUM or left in {"零", "十", "半"}:
            raise ValueError(f"无法识别数字: {value}")
        total = _CN_NUM[left] * 100
        remainder = remainder.removeprefix("零")
    if "十" in remainder:
        left, right = remainder.split("十", 1)
        if left and left not in _CN_NUM:
            raise ValueError(f"无法识别数字: {value}")
        if right and right not in _CN_NUM:
            raise ValueError(f"无法识别数字: {value}")
        total += _CN_NUM.get(left, 1) * 10 + _CN_NUM.get(right, 0)
        remainder = ""
    if remainder:
        if remainder not in _CN_NUM:
            raise ValueError(f"无法识别数字: {value}")
        total += _CN_NUM[remainder]
    if total:
        return float(total)
    raise ValueError(f"无法识别数字: {value}")


def _shift_months(day: date, months: int) -> date:
    # Avoid pandas Timestamp's version-dependent lower bound and clamp an
    # otherwise valid natural-language request to Python's date domain.
    month_index = (day.year - 1) * 12 + day.month - 1 + months
    max_month_index = (date.max.year - 1) * 12 + date.max.month - 1
    if month_index < 0:
        return date.min
    if month_index > max_month_index:
        return date.max
    zero_based_year, zero_based_month = divmod(month_index, 12)
    year = zero_based_year + 1
    month = zero_based_month + 1
    target_day = min(day.day, month_calendar.monthrange(year, month)[1])
    return date(year, month, target_day)


def parse_date_range(
    text: str, now: date | None = None
) -> tuple[date | None, date | None]:
    query = normalize_query(text)
    today = now or beijing_today()

    explicit = re.search(
        r"(20\d{2})[-/.年](\d{1,2})[-/.月](\d{1,2})日?\s*(?:到|至|~|—|-)\s*"
        r"(20\d{2})[-/.年](\d{1,2})[-/.月](\d{1,2})日?",
        query,
    )
    if explicit:
        values = [int(x) for x in explicit.groups()]
        try:
            start, end = date(*values[:3]), date(*values[3:])
        except ValueError as exc:
            raise ValueError("日期区间无效，请使用真实存在的 YYYY-MM-DD 日期") from exc
        return (start, end) if start <= end else (end, start)

    year_range = re.search(
        r"(?:从\s*)?(20\d{2})\s*年?\s*(?:到|至|~|—|-)\s*(20\d{2})\s*年?",
        query,
    )
    if year_range:
        first_year, last_year = map(int, year_range.groups())
        if first_year > last_year:
            first_year, last_year = last_year, first_year
        return date(first_year, 1, 1), date(last_year, 12, 31)

    recent = re.search(
        r"(?:最近|过去|近)\s*([零一二两三四五六七八九十百\d半]+)\s*个?\s*(年半|年|月)",
        query,
    )
    if recent:
        try:
            count = _number(recent.group(1))
        except ValueError as exc:
            raise ValueError("最近/过去时间范围中的数字无法识别") from exc
        unit = recent.group(2)
        if unit == "年半":
            months = max(1, round(count * 12 + 6))
        elif unit == "年":
            months = max(1, round(count * 12))
        else:
            months = max(1, round(count))
        return _shift_months(today, -months), today

    if "今年" in query:
        return date(today.year, 1, 1), today
    if "去年" in query:
        return date(today.year - 1, 1, 1), date(today.year - 1, 12, 31)
    if "前年" in query:
        return date(today.year - 2, 1, 1), date(today.year - 2, 12, 31)

    year_month = re.search(r"(20\d{2})[年/-](\d{1,2})月?", query)
    if year_month:
        year, month = map(int, year_month.groups())
        try:
            first = date(year, month, 1)
        except ValueError as exc:
            raise ValueError(f"月份无效: {year}-{month:02d}") from exc
        last = (pd.Timestamp(first) + pd.offsets.MonthEnd(0)).date()
        if "至今" in query:
            return (first, today) if first <= today else (today, first)
        return first, last

    year = re.search(r"(20\d{2})\s*年", query)
    if year:
        value = int(year.group(1))
        first = date(value, 1, 1)
        if "至今" in query:
            return (first, today) if first <= today else (today, first)
        return first, date(value, 12, 31)
    return None, None


def _products_from_query(query: str) -> tuple[str, ...]:
    upper = query.upper()
    wants_ic = (
        bool(re.search(r"(?<![A-Z])(IC|SC)(?![A-Z])", upper)) or "中证500" in query
    )
    wants_im = bool(re.search(r"(?<![A-Z])IM(?![A-Z])", upper)) or "中证1000" in query
    if wants_ic and not wants_im:
        return ("IC",)
    if wants_im and not wants_ic:
        return ("IM",)
    return ("IC", "IM")


def classify_query(text: str, now: date | None = None) -> QueryIntent:
    query = normalize_query(text)
    products = _products_from_query(query)
    performance = bool(
        re.search(r"表现|净值|回撤|收益曲线|历史收益|年化|夏普|回报", query)
    )
    intraday_signal = bool(re.search(r"(?:实时|盘中)\s*信号", query))
    close_signal = "信号" in query and not intraday_signal
    params = "参数" in query or "规则" in query or "阈值" in query
    parsed_start, parsed_end = parse_date_range(query, now)
    if performance:
        if parsed_start is None:
            today = now or beijing_today()
            parsed_start, parsed_end = _shift_months(today, -12), today
        return QueryIntent("performance", products, parsed_start, parsed_end)
    # Intentional single-route policy: explicit parameter/rule/threshold wording
    # takes precedence over signal wording in an ambiguous combined request.
    if params:
        return QueryIntent("params", products)
    if intraday_signal:
        return QueryIntent("intraday_signal", products)
    if close_signal:
        return QueryIntent("close_signal", products)
    if parsed_start is not None:
        return QueryIntent("performance", products, parsed_start, parsed_end)
    return QueryIntent("snapshot", products)


def decode_returns(product: str) -> pd.Series:
    raw = zlib.decompress(base64.b64decode(_RETURN_BLOBS[product]))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != _RETURN_SHA256[product]:
        raise RuntimeError(f"{product} 历史收益内嵌数据哈希校验失败")
    frame = pd.read_csv(io.BytesIO(raw), parse_dates=["date"])
    series = frame.set_index("date")["ret"].astype(float).sort_index()
    if series.index.has_duplicates or not series.index.is_monotonic_increasing:
        raise RuntimeError(f"{product} 历史收益日期异常")
    return series


def decode_benchmark_prices(product: str, index: pd.DatetimeIndex) -> pd.Series:
    raw = zlib.decompress(base64.b64decode(_BENCHMARK_PRICE_BLOBS[product]))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != _BENCHMARK_PRICE_SHA256[product]:
        raise RuntimeError(f"{product} 指数价格内嵌数据哈希校验失败")
    deltas = np.frombuffer(raw, dtype="<i4")
    if len(deltas) != len(index):
        raise RuntimeError(
            f"{product} 指数价格行数 {len(deltas)} 与正式收益 {len(index)} 不一致"
        )
    prices = np.cumsum(deltas, dtype=np.int64).astype(float) / 100.0
    series = pd.Series(prices, index=index, name="benchmark_price")
    if not np.isfinite(series).all() or (series <= 0).any():
        raise RuntimeError(f"{product} 指数价格内嵌数据异常")
    return series


@contextmanager
def _network_budget(seconds: float):
    """Bound HTTP calls without allowing a child scope to extend its parent."""

    parent = _NETWORK_DEADLINE.get()
    candidate = time_module.monotonic() + seconds
    deadline = min(parent, candidate) if parent is not None else candidate
    token = _NETWORK_DEADLINE.set(deadline)
    try:
        yield
    finally:
        _NETWORK_DEADLINE.reset(token)


def _bounded_timeout(cap: float) -> float:
    deadline = _NETWORK_DEADLINE.get()
    if deadline is None:
        return cap
    remaining = deadline - time_module.monotonic()
    if remaining <= 0.25:
        raise RuntimeError("联网请求超过总时间预算，已停止继续取数")
    return max(0.25, min(cap, remaining))


def _remaining_network_budget() -> float | None:
    deadline = _NETWORK_DEADLINE.get()
    if deadline is None:
        return None
    return max(0.0, deadline - time_module.monotonic())


def _signal_product_network_budget(product_count: int) -> float:
    if product_count <= 0:
        raise ValueError("信号品种数必须为正")
    return min(
        SIGNAL_PRODUCT_NETWORK_BUDGET_SECONDS,
        SIGNAL_NETWORK_BUDGET_SECONDS / product_count,
    )


def _cffex_month_archive(month: pd.Timestamp) -> bytes:
    key = month.strftime("%Y%m")
    if key not in _CFFEX_MONTH_CACHE:
        path = f"www.cffex.com.cn/sj/historysj/{key}/zip/{key}.zip"
        urls = [f"https://{path}", f"http://{path}"]
        failures: list[str] = []
        for url in urls:
            attempts = 1 if url.startswith("https://") else 3
            for attempt in range(attempts):
                try:
                    response = requests.get(
                        url,
                        timeout=_bounded_timeout(
                            5 if url.startswith("https://") else 15
                        ),
                        headers={
                            "User-Agent": "Mozilla/5.0",
                            "Cache-Control": "no-cache",
                        },
                        stream=True,
                    )
                    response.raise_for_status()
                    declared_size = response.headers.get("Content-Length")
                    if declared_size and int(declared_size) > MAX_CFFEX_DOWNLOAD_BYTES:
                        raise RuntimeError(f"中金所 {key} 月度行情包超过下载上限")
                    chunks: list[bytes] = []
                    downloaded = 0
                    for chunk in response.iter_content(chunk_size=64 * 1024):
                        if not chunk:
                            continue
                        downloaded += len(chunk)
                        if downloaded > MAX_CFFEX_DOWNLOAD_BYTES:
                            raise RuntimeError(f"中金所 {key} 月度行情包超过下载上限")
                        chunks.append(chunk)
                    content = b"".join(chunks)
                    if not content.startswith(b"PK"):
                        raise RuntimeError(f"中金所 {key} 月度行情包格式异常")
                    _CFFEX_MONTH_CACHE[key] = content
                    break
                except (requests.RequestException, RuntimeError) as exc:
                    transport = "HTTPS" if url.startswith("https://") else "HTTP"
                    failures.append(f"{transport} {type(exc).__name__}: {exc}")
                    if attempt + 1 < attempts:
                        time_module.sleep(0.5 * (attempt + 1))
            if key in _CFFEX_MONTH_CACHE:
                break
        if key not in _CFFEX_MONTH_CACHE:
            raise RuntimeError(
                f"中金所 {key} 月度行情包HTTPS/HTTP同源下载失败｜"
                + "｜".join(failures)
            )
    return _CFFEX_MONTH_CACHE[key]


def _cffex_historical_quote_frame(
    product: str, day: date, clock: datetime
) -> pd.DataFrame:
    """Load one official completed session from CFFEX's monthly archive."""

    raw = _cffex_month_archive(pd.Timestamp(day))
    member_name = f"{day:%Y%m%d}_1.csv"
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        members = archive.infolist()
        if len(members) > MAX_CFFEX_ZIP_MEMBERS:
            raise RuntimeError("中金所月度行情包成员数量超过安全上限")
        if any(info.file_size > MAX_CFFEX_ZIP_MEMBER_BYTES for info in members):
            raise RuntimeError("中金所月度行情包单个成员超过安全上限")
        if sum(info.file_size for info in members) > MAX_CFFEX_ZIP_UNCOMPRESSED_BYTES:
            raise RuntimeError("中金所月度行情包解压体积超过安全上限")
        matches = [info for info in members if info.filename.endswith(member_name)]
        if len(matches) != 1:
            raise RuntimeError(f"中金所月度行情包缺少唯一日文件 {member_name}")
        daily = pd.read_csv(
            io.BytesIO(archive.read(matches[0])), encoding="gbk", low_memory=False
        )
    daily.columns = [str(column).strip().lstrip("\ufeff") for column in daily.columns]
    field_map = {
        "合约代码": "instrument",
        "今开盘": "openprice",
        "最高价": "highest",
        "最低价": "lowest",
        "成交量": "volume",
        "持仓量": "position",
        "今收盘": "lastprice",
    }
    missing = sorted(set(field_map).difference(daily.columns))
    if missing:
        raise RuntimeError(
            f"中金所 {day} 日行情缺少字段: {', '.join(missing)}"
        )
    frame = daily.rename(columns=field_map)[list(field_map.values())].copy()
    frame["instrument"] = frame["instrument"].astype(str).str.strip().str.upper()
    pattern = rf"{product}\d{{4}}" if product in {"IC", "IM"} else r"MO\d{4}-[CP]-\d+"
    frame = frame.loc[frame["instrument"].str.fullmatch(pattern)].copy()
    if frame.empty:
        raise RuntimeError(f"中金所 {day} 日行情没有 {product} 合约")
    frame["source_date"] = day
    frame["source_time"] = "15:15:00"
    return _validate_quote_frame(frame, product, clock, "中金所官方日行情")


def fetch_cffex_daily_marks(
    contracts: Iterable[str], start: date, end: date
) -> pd.DataFrame:
    wanted = set(contracts)
    rows: list[dict[str, Any]] = []
    for month in pd.period_range(start=start, end=end, freq="M"):
        raw = _cffex_month_archive(month.to_timestamp())
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            members = archive.infolist()
            if len(members) > MAX_CFFEX_ZIP_MEMBERS:
                raise RuntimeError("中金所月度行情包成员数量超过安全上限")
            if any(info.file_size > MAX_CFFEX_ZIP_MEMBER_BYTES for info in members):
                raise RuntimeError("中金所月度行情包单个成员超过安全上限")
            if sum(info.file_size for info in members) > MAX_CFFEX_ZIP_UNCOMPRESSED_BYTES:
                raise RuntimeError("中金所月度行情包解压体积超过安全上限")
            if any(info.flag_bits & 0x1 for info in members):
                raise RuntimeError("中金所月度行情包含加密成员")
            for info in members:
                name = info.filename
                match = re.search(r"(20\d{6})_1\.csv$", name)
                if not match:
                    continue
                day = pd.Timestamp(match.group(1)).date()
                if day < start or day > end:
                    continue
                daily = pd.read_csv(
                    io.BytesIO(archive.read(info)), encoding="gbk", low_memory=False
                )
                daily.columns = [str(column).strip().lstrip("\ufeff") for column in daily.columns]
                field_map = {
                    "合约代码": "contract",
                    "今收盘": "close",
                    "今结算": "settle",
                    "前结算": "pre_settle",
                }
                missing_fields = set(field_map).difference(daily.columns)
                if missing_fields:
                    raise RuntimeError(
                        f"中金所 {day} 日行情缺少字段: {', '.join(sorted(missing_fields))}"
                    )
                daily = daily.rename(columns=field_map)
                contract_values = daily["contract"].astype(str).str.strip()
                selected = daily.loc[contract_values.isin(wanted)]
                for _, item in selected.iterrows():
                    rows.append(
                        {
                            "date": pd.Timestamp(day),
                            "contract": str(item["contract"]).strip(),
                            "close": float(pd.to_numeric(item["close"], errors="raise")),
                            "settle": float(pd.to_numeric(item["settle"], errors="raise")),
                            "pre_settle": float(
                                pd.to_numeric(item["pre_settle"], errors="raise")
                            ),
                        }
                    )
    if not rows:
        raise RuntimeError("中金所尚未提供所选区间的日行情")
    frame = pd.DataFrame(rows).sort_values(["date", "contract"])
    if frame.duplicated(["date", "contract"]).any():
        raise RuntimeError("中金所日行情出现重复合约记录")
    return frame.set_index(["date", "contract"])


def fetch_sina_option_closes(security_id: str) -> pd.Series:
    url = (
        "https://stock.finance.sina.com.cn/futures/api/jsonp_v2.php//"
        "StockOptionDaylineService.getSymbolInfo"
    )
    response = requests.get(
        url,
        params={"symbol": security_id},
        timeout=_bounded_timeout(8),
        headers={"User-Agent": "Mozilla/5.0", "Cache-Control": "no-cache"},
    )
    response.raise_for_status()
    match = re.search(r"\((\[.*\])\)\s*;?\s*$", response.text, flags=re.DOTALL)
    if not match:
        raise RuntimeError(f"上交所期权 {security_id} 历史行情响应格式异常")
    payload = json.loads(match.group(1))
    points = {
        pd.Timestamp(item["d"]): float(item["c"])
        for item in payload
        if item.get("d") and item.get("c") not in (None, "")
    }
    if not points:
        raise RuntimeError(f"上交所期权 {security_id} 未返回日收盘价")
    return pd.Series(points, dtype=float, name="put_mark").sort_index()


def fetch_sina_510500_security_id(contract: str) -> str:
    match = re.fullmatch(r"510500P(\d{4})([MA])(\d{5})", contract)
    if not match:
        raise RuntimeError(f"无法为IC Put解析新浪证券代码: {contract}")
    yymm, style, strike_code = match.groups()
    response = requests.get(
        "https://hq.sinajs.cn/",
        params={"list": f"OP_DOWN_510500{yymm}"},
        timeout=_bounded_timeout(8),
        headers={
            "User-Agent": "Mozilla/5.0 POE-IC-IM-Research/1.0",
            "Referer": "https://stock.finance.sina.com.cn/",
            "Cache-Control": "no-cache",
        },
    )
    response.raise_for_status()
    listing = response.content.decode("gbk", errors="replace")
    ids = re.findall(r"CON_OP_(\d+)", listing)
    if not ids:
        raise RuntimeError(f"新浪未返回510500 Put月份 {yymm} 的证券代码列表")
    details = requests.get(
        "https://hq.sinajs.cn/list="
        + ",".join(f"CON_OP_{value}" for value in ids),
        timeout=_bounded_timeout(8),
        headers={
            "User-Agent": "Mozilla/5.0 POE-IC-IM-Research/1.0",
            "Referer": "https://stock.finance.sina.com.cn/",
            "Cache-Control": "no-cache",
        },
    )
    details.raise_for_status()
    text = details.content.decode("gbk", errors="replace")
    matches: list[str] = []
    for security_id, payload in re.findall(
        r'hq_str_CON_OP_(\d+)="([^"]*)"', text
    ):
        fields = payload.split(",")
        if len(fields) <= 46:
            continue
        try:
            strike_match = int(round(float(fields[7]) * 1000)) == int(strike_code)
        except ValueError:
            continue
        expiry_match = str(fields[46]).replace("-", "")[2:6] == yymm
        if fields[43] == style and fields[45] == "P" and strike_match and expiry_match:
            matches.append(security_id)
    if len(matches) != 1:
        raise RuntimeError(
            f"新浪证券代码映射不唯一: {contract} -> {sorted(matches)}"
        )
    return matches[0]


def _contract_daily_marks(
    marks: pd.DataFrame, contract: str, product: str, leg: str
) -> pd.DataFrame:
    try:
        return marks.xs(contract, level="contract").sort_index()
    except KeyError as exc:
        raise RuntimeError(
            f"{product} {leg}日行情缺少合约 {contract}"
        ) from exc


def latest_continuation_frame(product: str, end: date) -> pd.DataFrame:
    if end > DATA_CUTOFF:
        raise RuntimeError(
            "1.3逐日仓位、期权与网格续接账本尚未形成；禁止用固定1倍期货桥接冒充1.3绩效，"
            f"绩效仅可降级到已哈希冻结的 {DATA_CUTOFF}"
        )
    anchor = LIVE_CONTINUATION_ANCHOR[product]
    effective_end = min(end, anchor["last_verified_day"])
    start = DATA_CUTOFF + timedelta(days=1)
    if effective_end < start:
        return pd.DataFrame(
            columns=["ret", "benchmark_price", "is_live", "is_transition"]
        )

    contracts = [anchor["core_contract"], anchor["post_core_contract"]]
    if product == "IM":
        contracts.extend(
            [
                anchor["put_contract"],
                anchor["call_contract"],
                anchor["post_put_contract"],
            ]
        )
    marks = fetch_cffex_daily_marks(contracts, start, effective_end)
    benchmark = fetch_price_history(product)
    benchmark.index = pd.to_datetime(benchmark.index).normalize()

    core = _contract_daily_marks(
        marks, str(anchor["core_contract"]), product, "核心期货"
    )
    core = core.loc[(core.index.date >= start) & (core.index.date <= effective_end)]
    if core.empty:
        raise RuntimeError(f"{product} 暂无 {DATA_CUTOFF} 之后的已完成交易日")
    first_day = core.index[0]
    first_pre_settle = float(core.iloc[0]["pre_settle"])
    if not math.isclose(
        first_pre_settle, float(anchor["core_settle"]), rel_tol=0.0, abs_tol=1e-6
    ):
        raise RuntimeError(
            f"{product} 续接锚点不连续：{first_day.date()} 前结算 {first_pre_settle:g} "
            f"!= 正式段末值 {float(anchor['core_settle']):g}"
        )
    missing_benchmark = core.index.difference(benchmark.index)
    if len(missing_benchmark):
        raise RuntimeError(
            f"{product} 指数缺少 {missing_benchmark[0].date()} 的收盘价"
        )

    rows: list[dict[str, Any]] = []
    if product == "IC":
        option = fetch_sina_option_closes(anchor["put_security_id"])
        post_option = fetch_sina_option_closes(anchor["post_put_security_id"])
        cutoff_stamp = pd.Timestamp(DATA_CUTOFF)
        if cutoff_stamp not in option.index:
            raise RuntimeError(
                f"IC Put续接锚点缺少正式段末日 {DATA_CUTOFF} 的新浪历史收盘"
            )
        cutoff_mark = float(option.loc[cutoff_stamp])
        if not math.isclose(
            cutoff_mark, float(anchor["put_mark"]), rel_tol=0.0, abs_tol=1e-6
        ):
            raise RuntimeError(
                f"IC Put续接锚点不连续：{DATA_CUTOFF} 新浪收盘 {cutoff_mark:g} "
                f"!= 正式段末值 {float(anchor['put_mark']):g}"
            )
        missing_option = core.index.difference(option.index)
        if len(missing_option):
            raise RuntimeError(
                f"IC 期权缺少 {missing_option[0].date()} 的实际收盘价"
            )
        prior_mark = float(anchor["put_mark"])
        qty = float(anchor["put_qty"])
        notional_fraction = qty / float(anchor["put_full_qty"])
        for day, item in core.iterrows():
            settle = float(item["settle"])
            pre_settle = float(item["pre_settle"])
            mark = float(option.loc[day])
            gross = settle / pre_settle - 1.0
            put_pnl = qty * 10_000.0 * (mark - prior_mark) / (pre_settle * 200.0)
            futures_cost = 0.0
            put_cost = 0.0
            eod_settle = settle
            eod_mark = mark
            eod_qty = qty
            is_transition = day.date() == anchor["transition_day"]

            if day.date() == anchor["resize_day"]:
                eod_qty = float(anchor["resized_put_qty"])
                new_fraction = eod_qty / float(anchor["put_full_qty"])
                put_cost += abs(new_fraction - notional_fraction) * 0.0001
                notional_fraction = new_fraction

            if is_transition:
                post_core = _contract_daily_marks(
                    marks, str(anchor["post_core_contract"]), product, "展期后核心期货"
                )
                if day not in post_core.index or day not in post_option.index:
                    raise RuntimeError(f"IC 月换日 {day.date()} 缺少新期货或新Put收盘")
                eod_settle = float(post_core.loc[day, "settle"])
                eod_mark = float(post_option.loc[day])
                eod_qty = float(anchor["post_put_qty"])
                new_fraction = eod_qty / float(anchor["post_put_full_qty"])
                put_cost += (notional_fraction + new_fraction) * 0.0001
                notional_fraction = new_fraction
                futures_cost = 2.0 * 0.0001

            put_mark_fraction = (
                eod_qty * 10_000.0 * eod_mark / (eod_settle * 200.0)
            )
            cash_weight = max(0.0, 1.0 - 0.30 - put_mark_fraction)
            futures_net = (1.0 + gross) * (1.0 - futures_cost) - 1.0
            ret = (
                (1.0 + futures_net + put_pnl) * (1.0 - put_cost)
                - 1.0
                + cash_weight * CASH_DAILY
            )
            rows.append(
                {
                    "date": day,
                    "ret": ret,
                    "benchmark_price": float(benchmark.loc[day]),
                    "is_live": True,
                    "is_transition": is_transition,
                }
            )
            prior_mark = eod_mark
            qty = eod_qty
    else:
        put = _contract_daily_marks(
            marks, str(anchor["put_contract"]), product, "Put"
        )
        call = _contract_daily_marks(
            marks, str(anchor["call_contract"]), product, "Call"
        )
        post_core = _contract_daily_marks(
            marks, str(anchor["post_core_contract"]), product, "展期后核心期货"
        )
        post_put = _contract_daily_marks(
            marks, str(anchor["post_put_contract"]), product, "展期后Put"
        )
        missing_put = core.index.difference(put.index)
        missing_call = core.index.difference(call.index)
        if len(missing_put) or len(missing_call):
            missing = missing_put[0] if len(missing_put) else missing_call[0]
            raise RuntimeError(f"IM 期权缺少 {missing.date()} 的实际结算价")
        for leg, series, expected in (
            ("Put", put, anchor["put_mark"]),
            ("Call", call, anchor["call_mark"]),
        ):
            actual = float(series.loc[first_day, "pre_settle"])
            if not math.isclose(actual, float(expected), rel_tol=0.0, abs_tol=1e-6):
                raise RuntimeError(
                    f"IM {leg}续接锚点不连续：{first_day.date()} 前结算 {actual:g} "
                    f"!= 正式段末值 {float(expected):g}"
                )
        prior_put = float(anchor["put_mark"])
        prior_call = float(anchor["call_mark"])
        put_units = float(anchor["put_equivalent_units"])
        call_units = float(anchor["call_equivalent_units"])
        strike = float(anchor["call_strike"])
        for day, item in core.iterrows():
            settle = float(item["settle"])
            pre_settle = float(item["pre_settle"])
            put_mark = float(put.loc[day, "settle"])
            call_mark = float(call.loc[day, "settle"])
            spot = float(benchmark.loc[day])
            gross = settle / pre_settle - 1.0
            put_pnl = put_units * (put_mark - prior_put) / pre_settle
            call_pnl = -call_units * (call_mark - prior_call) / pre_settle
            is_transition = day.date() == anchor["transition_day"]
            futures_cost = 0.0
            put_cost = 0.0
            call_cost = 0.0
            eod_settle = settle
            eod_put_mark = put_mark
            eod_call_mark = call_mark
            eod_put_units = put_units
            eod_call_units = call_units

            if is_transition:
                if day not in post_core.index or day not in post_put.index:
                    raise RuntimeError(f"IM 月换日 {day.date()} 缺少新期货或新Put结算")
                eod_settle = float(post_core.loc[day, "settle"])
                eod_put_mark = float(post_put.loc[day, "settle"])
                eod_call_mark = 0.0
                eod_put_units = float(anchor["post_put_equivalent_units"])
                eod_call_units = 0.0
                futures_cost = 2.0 * 0.0001
                # Parent path rolls 1.5 full-notional Put fractions each side;
                # v1.3 carries only half of that core sleeve.
                put_cost = 0.5 * (1.5 + 1.5) * 0.0001

            put_mark_fraction = eod_put_units * eod_put_mark / eod_settle
            out_of_money = max(strike - spot, 0.0)
            call_margin = eod_call_units * (
                eod_call_mark + max(0.12 * spot - out_of_money, 0.07 * spot)
            ) / eod_settle
            cash_weight = max(
                0.0, 1.0 - 0.30 - put_mark_fraction - call_margin
            )
            ret = (
                (1.0 + gross + put_pnl + call_pnl)
                * (1.0 - futures_cost)
                * (1.0 - put_cost)
                * (1.0 - call_cost)
                - 1.0
                + cash_weight * CASH_DAILY
            )
            rows.append(
                {
                    "date": day,
                    "ret": ret,
                    "benchmark_price": spot,
                    "is_live": True,
                    "is_transition": is_transition,
                }
            )
            prior_put = eod_put_mark
            prior_call = eod_call_mark
            put_units = eod_put_units
            call_units = eod_call_units

    result = pd.DataFrame(rows).set_index("date").sort_index()
    if not np.isfinite(result[["ret", "benchmark_price"]]).all().all():
        raise RuntimeError(f"{product} 最新续接收益含无效值")
    return result


def performance_frame(
    product: str, start: date, end: date, *, refresh_latest: bool = False
) -> pd.DataFrame:
    returns = decode_returns(product)
    benchmark_prices = decode_benchmark_prices(product, returns.index)
    live_flags = pd.Series(False, index=returns.index, dtype=bool)
    transition_flags = pd.Series(False, index=returns.index, dtype=bool)
    if refresh_latest and end > DATA_CUTOFF:
        continuation = latest_continuation_frame(product, end)
        if not continuation.empty:
            returns = pd.concat([returns, continuation["ret"]]).sort_index()
            benchmark_prices = pd.concat(
                [benchmark_prices, continuation["benchmark_price"]]
            ).sort_index()
            live_flags = pd.concat(
                [live_flags, continuation["is_live"].astype(bool)]
            ).sort_index()
            continuation_transition = continuation.get(
                "is_transition",
                pd.Series(False, index=continuation.index, dtype=bool),
            )
            transition_flags = pd.concat(
                [transition_flags, continuation_transition.astype(bool)]
            ).sort_index()
    for label, series in (
        ("策略收益", returns),
        ("指数价格", benchmark_prices),
        ("数据段标记", live_flags),
        ("换仓日标记", transition_flags),
    ):
        if series.index.has_duplicates:
            duplicated = series.index[series.index.duplicated()][0]
            raise RuntimeError(
                f"{product} {label}存在重复交易日 {pd.Timestamp(duplicated).date()}"
            )
    selected = returns.loc[
        (returns.index.date >= start) & (returns.index.date <= end)
    ]
    if selected.empty:
        raise ValueError(f"{product} 在所选区间没有可核验收益数据")
    nav = (1.0 + selected).cumprod()
    drawdown = nav / nav.cummax() - 1.0
    benchmark_price = benchmark_prices.reindex(selected.index)
    if benchmark_price.isna().any():
        raise RuntimeError(f"{product} 指数价格与策略收益交易日未完全对齐")
    benchmark_nav = benchmark_price / float(benchmark_price.iloc[0])
    chart_nav = nav / float(nav.iloc[0])
    return pd.DataFrame(
        {
            "ret": selected,
            "nav": nav,
            "chart_nav": chart_nav,
            "drawdown": drawdown,
            "benchmark_price": benchmark_price,
            "benchmark_nav": benchmark_nav,
            "is_live": live_flags.reindex(selected.index).fillna(False).astype(bool),
            "is_transition": transition_flags.reindex(selected.index)
            .fillna(False)
            .astype(bool),
        }
    )


def performance_metrics(frame: pd.DataFrame) -> dict[str, float]:
    observations = len(frame)
    final_nav = float(frame["nav"].iloc[-1])
    std = float(frame["ret"].std(ddof=1)) if observations > 1 else 0.0
    return {
        "final_nav": final_nav,
        "return": final_nav - 1.0,
        "cagr": final_nav ** (252.0 / observations) - 1.0,
        "volatility": std * np.sqrt(252.0),
        "sharpe": float(frame["ret"].mean()) / std * np.sqrt(252.0) if std > 0 else 0.0,
        "max_drawdown": float(frame["drawdown"].min()),
        "observations": float(observations),
    }


def render_nav_drawdown_chart(product: str, frame: pd.DataFrame, start: date) -> bytes:
    color = "#1f77b4" if product == "IC" else "#d95f02"
    fig, (nav_ax, dd_ax) = plt.subplots(
        2, 1, figsize=(11.5, 7.5), sharex=True, gridspec_kw={"height_ratios": [3, 1]}
    )
    benchmark_name = "CSI 500 Price Index" if product == "IC" else "CSI 1000 Price Index"
    nav_ax.plot(
        frame.index,
        frame["chart_nav"],
        color=color,
        linewidth=1.9,
        label=f"{product} v1.3 NAV",
    )
    if frame["is_live"].any():
        first_live = int(np.flatnonzero(frame["is_live"].to_numpy())[0])
        live_part = frame.iloc[max(0, first_live - 1) :]
        nav_ax.plot(
            live_part.index,
            live_part["chart_nav"],
            color="#7b3294",
            linewidth=2.2,
            label="Actual-market continuation",
        )
        if frame.index.min().date() <= DATA_CUTOFF:
            nav_ax.axvline(
                pd.Timestamp(DATA_CUTOFF),
                color="#7b3294",
                linewidth=0.9,
                linestyle=":",
            )
    nav_ax.plot(
        frame.index,
        frame["benchmark_nav"],
        color="#4d4d4d",
        linewidth=1.4,
        linestyle="--",
        label=f"{benchmark_name} (normalized)",
    )
    nav_ax.axhline(1.0, color="#777777", linewidth=0.8, linestyle="--")
    nav_ax.set_title(
        f"{product} v1.3 History + Actual Continuation vs {benchmark_name} | "
        f"{start} to {frame.index[-1].date()}"
    )
    nav_ax.set_ylabel("NAV (start = 1.0)")
    nav_ax.legend(loc="best", frameon=False)
    nav_ax.grid(alpha=0.25)
    dd_ax.fill_between(frame.index, frame["drawdown"], 0, color="#c44e52", alpha=0.4)
    dd_ax.plot(frame.index, frame["drawdown"], color="#a23b3b", linewidth=1.0)
    dd_ax.set_ylabel("Drawdown")
    dd_ax.set_xlabel("Date")
    dd_ax.grid(alpha=0.25)
    dd_ax.yaxis.set_major_formatter(lambda value, _pos: f"{value:.0%}")
    fig.tight_layout()
    buffer = io.BytesIO()
    fig.savefig(buffer, format="png", dpi=150, bbox_inches="tight")
    plt.close(fig)
    return buffer.getvalue()


def valuation_score(pb: float, erp: float, dividend: float) -> float:
    pressures = ((pb - 1.50) / 0.50, (0.045 - erp) / 0.015, (0.030 - dividend) / 0.010)
    return float(np.median(pressures))


def _tier(score: float, thresholds: Iterable[float]) -> int:
    return sum(score + 1e-12 >= threshold for threshold in thresholds)


def _tier_band_label(
    tier: int, thresholds: tuple[float, ...], *, unit: str = ""
) -> str:
    if tier <= 0:
        return f"基础观察档（低于{thresholds[0]:.3f}{unit}）"
    if tier >= len(thresholds):
        return f"第{tier}保护档（不低于{thresholds[-1]:.3f}{unit}）"
    return (
        f"第{tier}保护档（{thresholds[tier - 1]:.3f}至"
        f"低于{thresholds[tier]:.3f}{unit}）"
    )


def ic_targets(score: float, momentum_120: float) -> dict[str, Any]:
    thresholds = (1.90, 1.95, 2.00, 2.05)
    tier = _tier(score, thresholds)
    valuation_delta = (0.0, 0.25, 0.50, 0.75, 1.00)[tier]
    mom120_floor = 0.50 if momentum_120 < 0 else 0.0
    delta = max(valuation_delta, mom120_floor)
    if valuation_delta > mom120_floor:
        driver = "估值档"
    elif mom120_floor > valuation_delta:
        driver = "MOM120负动量下限"
    elif delta > 0:
        driver = "估值档与MOM120下限同时命中同一目标"
    else:
        driver = "基础观察档，未触发Put"
    return {
        "put_delta": delta,
        "valuation_tier": tier,
        "valuation_tier_label": _tier_band_label(tier, thresholds),
        "valuation_put_delta": valuation_delta,
        "mom120_floor_delta": mom120_floor,
        "put_driver": driver,
        "grid_next": score <= 0.375,
        "grid_exit": score >= 1.000,
    }


def im_targets(score: float, momentum_120: float) -> dict[str, Any]:
    absolute_thresholds = (2.45, 2.50, 2.60)
    relative_thresholds = tuple(FROZEN["IM"]["relative_thresholds"])
    absolute = _tier(score, absolute_thresholds)
    relative = _tier(score, relative_thresholds)
    valuation_puts = max(absolute, relative)
    mom120_floor = 3 if momentum_120 < 0 else 0
    puts = max(valuation_puts, mom120_floor)
    if valuation_puts > mom120_floor:
        driver = "估值档"
    elif mom120_floor > valuation_puts:
        driver = "MOM120负动量下限"
    elif puts > 0:
        driver = "估值档与MOM120下限同时命中同一目标"
    else:
        driver = "估值两轴均在基础观察档，未触发Put"
    return {
        "puts_per_core": min(4, puts),
        "absolute_valuation_tier": absolute,
        "absolute_valuation_tier_label": _tier_band_label(
            absolute, absolute_thresholds
        ),
        "relative_valuation_tier": relative,
        "relative_valuation_tier_label": _tier_band_label(
            relative, relative_thresholds
        ),
        "valuation_puts_per_full_core": valuation_puts,
        "mom120_floor_puts_per_full_core": mom120_floor,
        "put_driver": driver,
        "grid_next": score <= 1.60,
        "grid_exit": score >= 2.00,
    }


def calc_v13_momentum_score(product: str, close: pd.Series) -> pd.Series:
    """Exact weighted bias-momentum score inherited from A-share v1.3."""

    rule = MOMENTUM_RULES[product]
    prices = pd.to_numeric(close, errors="coerce").to_numpy(dtype=float)
    result = np.full(len(prices), np.nan)
    ma_days = int(rule["ma"])
    momentum_days = int(rule["days"])
    ma = pd.Series(prices, index=close.index).rolling(ma_days).mean().to_numpy(dtype=float)
    with np.errstate(divide="ignore", invalid="ignore"):
        bias = np.where((ma > 1e-10) & np.isfinite(prices), prices / ma, np.nan)
    x = np.arange(momentum_days, dtype=float)
    weights = np.linspace(1.0, float(rule["weight_end"]), momentum_days)
    weight_sum = float(weights.sum())
    x_bar = float((weights * x).sum() / weight_sum)
    denominator = float((weights * (x - x_bar) ** 2).sum())
    for end in range(ma_days + momentum_days - 1, len(prices)):
        y = bias[end - momentum_days + 1 : end + 1]
        if not np.isfinite(y).all() or y[0] <= 1e-10:
            continue
        y_bar = float((weights * y).sum() / weight_sum)
        slope = float((weights * (x - x_bar) * (y - y_bar)).sum() / denominator)
        result[end] = slope / float(y[0]) * 10000.0
    return pd.Series(result, index=close.index, name="momentum_score")


def _validate_v13_ohlcv(product: str, frame: pd.DataFrame, clock: datetime) -> pd.DataFrame:
    if frame.empty:
        raise RuntimeError(f"{product} OHLCV为空")
    required = ["open", "high", "low", "close", "volume"]
    missing = [column for column in required if column not in frame.columns]
    if missing:
        raise RuntimeError(f"{product} OHLCV缺列: {missing}")
    result = frame[required].copy()
    index = pd.DatetimeIndex(pd.to_datetime(result.index, errors="raise"))
    if index.tz is not None:
        index = index.tz_convert(BEIJING).tz_localize(None)
    result.index = index.normalize()
    if result.index.has_duplicates or not result.index.is_monotonic_increasing:
        raise RuntimeError(f"{product} OHLCV日期重复或乱序")
    result = result.apply(pd.to_numeric, errors="coerce").astype(float)
    if not np.isfinite(result.to_numpy(dtype=float)).all():
        raise RuntimeError(f"{product} OHLCV含NaN或无穷值")
    prices = result[["open", "high", "low", "close"]]
    if (prices <= 0.0).any().any():
        raise RuntimeError(f"{product} OHLCV含非正价格")
    if (result["high"] < prices[["open", "close"]].max(axis=1)).any():
        raise RuntimeError(f"{product} OHLCV最高价关系错误")
    if (result["low"] > prices[["open", "close"]].min(axis=1)).any():
        raise RuntimeError(f"{product} OHLCV最低价关系错误")
    if (result["volume"] <= 0.0).any():
        raise RuntimeError(f"{product} OHLCV成交量非正")
    recent_volume_median = float(result["volume"].tail(min(len(result), 60)).median())
    if not 1_000_000.0 <= recent_volume_median <= 1_000_000_000_000.0:
        raise RuntimeError(f"{product} OHLCV成交量单位/数量级异常")
    replay_day = _HISTORICAL_REPLAY_DAY.get()
    if replay_day is not None:
        result = result.loc[result.index.date <= replay_day]
    if result.empty or result.index[-1].date() > clock.date():
        raise RuntimeError(f"{product} OHLCV日期范围无效")
    expected = _latest_completed_exchange_day(clock)
    if result.index[-1].date() < expected:
        raise RuntimeError(
            f"{product} OHLCV已过期：最新 {result.index[-1].date()}，应覆盖 {expected}"
        )
    history_start, history_rows, expected_history_hash = V13_HISTORY_DATE_INDEX[product]
    fixed_dates = result.loc[
        (result.index.date >= history_start) & (result.index.date <= DATA_CUTOFF)
    ].index
    fixed_payload = "\n".join(fixed_dates.strftime("%Y-%m-%d")) + "\n"
    actual_history_hash = hashlib.sha256(fixed_payload.encode("utf-8")).hexdigest()
    if len(fixed_dates) != history_rows or actual_history_hash != expected_history_hash:
        raise RuntimeError(
            f"{product} OHLCV在{history_start}至{DATA_CUTOFF}的交易日索引不完整或被改写"
        )
    coverage_start = DATA_CUTOFF + timedelta(days=1)
    expected_days: set[date] = set()
    cursor = coverage_start
    last_day = result.index[-1].date()
    while cursor <= last_day:
        if _is_exchange_trading_day(cursor):
            expected_days.add(cursor)
        cursor += timedelta(days=1)
    actual_days = set(result.index.date)
    missing_days = sorted(expected_days - actual_days)
    if missing_days:
        preview = ", ".join(day.isoformat() for day in missing_days[:5])
        raise RuntimeError(
            f"{product} OHLCV交易日序列不完整，缺失{len(missing_days)}日：{preview}"
        )
    return result


def v13_momentum_schedule(
    product: str, close: pd.Series, ohlcv: pd.DataFrame | None = None
) -> pd.DataFrame:
    indicator_close = close.copy()
    score = calc_v13_momentum_score(product, indicator_close)
    abs20 = (indicator_close / indicator_close.shift(20) - 1.0).rename("abs20")
    if product == "IC":
        formal_start = pd.Timestamp(MOMENTUM_RULES[product]["formal_start"])
        close = indicator_close.loc[indicator_close.index >= formal_start]
        if close.empty or close.index[0] != formal_start:
            raise RuntimeError(
                "IC OHLCV必须完整覆盖2007-01-15起正式期；截断历史会重置NAV防御高水位"
            )
        score = score.reindex(close.index)
        abs20 = abs20.reindex(close.index)
        if not np.isfinite(float(score.iloc[0])) or not np.isfinite(float(abs20.iloc[0])):
            raise RuntimeError("IC OHLCV缺少正式期起点所需指标暖机历史")
    base_target = (score > 0).astype(float) * (
        0.5 + 0.5 * (abs20 > 0).astype(float)
    )
    volume_ratio = pd.Series(np.nan, index=close.index, name="volume_ratio")
    volume_pass = pd.Series(True, index=close.index, name="volume_pass")
    volume_placeholder = pd.Series(False, index=close.index, name="volume_placeholder")
    score_hot_signal = pd.Series(False, index=close.index, name="score_hot_signal")
    base_nav = pd.Series(np.nan, index=close.index, name="base_nav_for_dd")
    base_dd = pd.Series(np.nan, index=close.index, name="base_dd_for_gate")
    nav_decay_signal = pd.Series(False, index=close.index, name="nav_decay_signal")
    target = base_target.copy()
    if product == "IC":
        if ohlcv is None:
            raise RuntimeError("IC 1.3 NAV防守必须使用可验证OHLCV")
        rule = MOMENTUM_RULES[product]
        base_execution = base_target.shift(1, fill_value=0.0)
        raw_ret = close.pct_change().fillna(0.0)
        turnover = base_execution.diff().abs().fillna(base_execution.abs())
        daily_cash = (1.0 + float(rule["annual_cash_yield"])) ** (1.0 / 244.0) - 1.0
        cash_ret = (1.0 - base_execution).clip(lower=0.0, upper=1.0) * daily_cash
        if not cash_ret.empty:
            cash_ret.iloc[0] = 0.0
        base_ret = (
            base_execution * raw_ret
            + cash_ret
            - float(rule["cost_rate"]) * turnover
        )
        base_nav = (1.0 + base_ret).cumprod().rename("base_nav_for_dd")
        base_dd = (base_nav / base_nav.cummax() - 1.0).rename("base_dd_for_gate")
        nav_decay_signal = base_dd.le(-float(rule["nav_decay_threshold"])).rename(
            "nav_decay_signal"
        )
        target = base_target.where(
            ~nav_decay_signal,
            base_target * float(rule["nav_decay_scale"]),
        )
    elif product == "IM":
        if ohlcv is None:
            raise RuntimeError("IM 1.3动量必须使用可验证OHLCV，不能只传收盘价")
        aligned = ohlcv.reindex(close.index)
        if aligned[["volume"]].isna().any().any():
            raise RuntimeError("IM 1.3 OHLCV与收盘价日期错位")
        volume = pd.to_numeric(aligned["volume"], errors="coerce")
        rule = MOMENTUM_RULES[product]
        volume_ratio = (
            volume / volume.rolling(int(rule["volume_ma"])).mean()
        ).rename("volume_ratio")
        if "realtime_volume_placeholder" in aligned.columns:
            volume_placeholder = aligned["realtime_volume_placeholder"].eq(True)
            volume_ratio.loc[volume_placeholder] = volume_ratio.shift(1).loc[volume_placeholder]
        volume_pass = (
            (volume_ratio >= float(rule["volume_ratio_threshold"]))
            .where(volume_ratio.notna(), bool(rule["volume_warmup_passes"]))
            .astype(bool)
            .rename("volume_pass")
        )
        if volume_placeholder.any():
            volume_pass.loc[volume_placeholder] = volume_pass.shift(
                1, fill_value=True
            ).loc[volume_placeholder]
        target = base_target.where(volume_pass, 0.0)
        score_hot_signal = (
            (score >= float(rule["hot_score_threshold"])) & target.gt(0.0)
        ).rename("score_hot_signal")
        target = target.where(
            ~score_hot_signal, target * float(rule["hot_scale"])
        )
    target = target.rename("signal_target")
    return pd.DataFrame(
        {
            "close": close,
            "momentum_score": score,
            "abs20": abs20,
            "base_signal_target": base_target,
            "volume_ratio": volume_ratio,
            "volume_pass": volume_pass,
            "volume_placeholder": volume_placeholder,
            "score_hot_signal": score_hot_signal,
            "base_nav_for_dd": base_nav,
            "base_dd_for_gate": base_dd,
            "nav_decay_signal": nav_decay_signal,
            "signal_target": target,
            "execution_weight": target.shift(1, fill_value=0.0),
        }
    )


def _proxy_score_for_price(product: str, price: float) -> float:
    ratio = float(price) / float(FROZEN[product]["price"])
    proxy_pb = float(FROZEN[product]["pb"]) * ratio
    proxy_pe = float(FROZEN[product]["pe"]) * ratio
    proxy_erp = 1.0 / proxy_pe - float(FROZEN[product]["gov10y"])
    return valuation_score(proxy_pb, proxy_erp, float(FROZEN[product]["dividend"]))


def _momentum_120_at(close: pd.Series, index: int) -> float:
    if len(close) < 122 or abs(index) > len(close):
        raise RuntimeError("价格历史不足以计算前一日MOM120")
    position = index if index >= 0 else len(close) + index
    anchor = position - 120
    if anchor < 0:
        raise RuntimeError("价格历史不足以计算前一日MOM120")
    return float(close.iloc[position] / close.iloc[anchor] - 1.0)


def _replay_v13_grid(product: str, prices: pd.Series) -> tuple[float, float]:
    """Return current grid units and the newest T-close target for T+1 open."""

    rule = V13_GRID_RULES[product]
    state = float(V13_FROZEN[product]["grid_units"])
    eligible = prices[prices.index.date > DATA_CUTOFF]
    if eligible.empty:
        return state, state
    for value in eligible.iloc[:-1]:
        score = _proxy_score_for_price(product, float(value))
        if score <= rule["entry"]:
            state = 1.0
        elif score >= rule["exit"]:
            state = 0.0
    target = state
    last_score = _proxy_score_for_price(product, float(eligible.iloc[-1]))
    if last_score <= rule["entry"]:
        target = 1.0
    elif last_score >= rule["exit"]:
        target = 0.0
    return state, target


def _request_json(url: str, params: dict[str, Any]) -> dict[str, Any]:
    error: Exception | None = None
    for timeout in (5, 8):
        try:
            response = requests.get(
                url,
                params=params,
                timeout=_bounded_timeout(timeout),
                headers={
                    "User-Agent": "Mozilla/5.0 POE-IC-IM-Research/1.0",
                    "Cache-Control": "no-cache",
                    "Pragma": "no-cache",
                },
            )
            response.raise_for_status()
            return response.json()
        except requests.HTTPError as exc:
            status = exc.response.status_code if exc.response is not None else None
            if status is not None and status < 500 and status not in {408, 429}:
                raise RuntimeError(f"行情接口拒绝请求（HTTP {status}）") from exc
            error = exc
        except (requests.ConnectionError, requests.Timeout, ValueError) as exc:
            error = exc
    raise RuntimeError(f"行情接口不可用: {error}")


def fetch_live_price_quote(product: str) -> dict[str, Any]:
    # Tencent is the low-latency primary quote. EastMoney remains a compatible
    # fallback because Poe egress rules can differ between deployments.
    try:
        response = requests.get(
            f"https://qt.gtimg.cn/q={TENCENT_SYMBOLS[product]}",
            timeout=_bounded_timeout(6),
            headers={
                "User-Agent": "Mozilla/5.0",
                "Referer": "https://finance.qq.com/",
                "Cache-Control": "no-cache",
                "Pragma": "no-cache",
            },
        )
        response.raise_for_status()
        fields = (
            response.content.decode("gbk", errors="replace").split('"')[1].split("~")
        )
        price = float(fields[3])
        stamp = datetime.strptime(fields[30], "%Y%m%d%H%M%S").replace(
            tzinfo=BEIJING
        )
        if math.isfinite(price) and price > 0:
            return {
                "price": price,
                "source": "腾讯财经",
                "source_date": stamp.date(),
                "source_time": stamp.strftime("%H:%M:%S"),
            }
    except (requests.RequestException, ValueError, IndexError):
        pass

    payload = _request_json(
        "https://push2.eastmoney.com/api/qt/stock/get",
        {
            "secid": EASTMONEY_SECIDS[product],
            "fields": "f43,f44,f45,f60",
            "ut": "fa5fd1943c7b386f172d6893dbfba10b",
        },
    )
    data = payload.get("data") or {}
    price = float(data.get("f43", 0)) / 100.0
    if not math.isfinite(price) or price <= 0:
        raise RuntimeError(f"{product} 未取得有效实时价格")
    return {
        "price": price,
        "source": "东方财富",
        "source_date": None,
        "source_time": None,
    }


def fetch_live_price(product: str) -> float:
    return float(fetch_live_price_quote(product)["price"])


def fetch_price_history(product: str) -> pd.Series:
    try:
        key = TENCENT_SYMBOLS[product]
        payload = _request_json(
            "https://web.ifzq.gtimg.cn/appstock/app/kline/kline",
            {"param": f"{key},day,,,260"},
        )
        rows = ((payload.get("data") or {}).get(key) or {}).get("day") or []
        points = [
            (pd.Timestamp(row[0]), float(row[2])) for row in rows if len(row) >= 3
        ]
        if len(points) >= 121:
            return pd.Series(dict(points), dtype=float).sort_index()
    except (requests.RequestException, RuntimeError, ValueError, TypeError, IndexError):
        pass

    payload = _request_json(
        "https://push2his.eastmoney.com/api/qt/stock/kline/get",
        {
            "secid": EASTMONEY_SECIDS[product],
            "klt": "101",
            "fqt": "0",
            "lmt": "260",
            "end": "20500101",
            "fields1": "f1,f2,f3,f4,f5,f6",
            "fields2": "f51,f52,f53,f54,f55,f56",
            "ut": "fa5fd1943c7b386f172d6893dbfba10b",
        },
    )
    klines = (payload.get("data") or {}).get("klines") or []
    points = [
        (pd.Timestamp(parts[0]), float(parts[2]))
        for row in klines
        if len(parts := row.split(",")) >= 3
    ]
    if len(points) < 121:
        raise RuntimeError(f"{product} 价格历史不足120个交易日")
    return pd.Series(dict(points), dtype=float).sort_index()


def fetch_ohlcv_history(product: str) -> pd.DataFrame:
    """Fetch raw daily index OHLCV using the A-share v1.3 source order."""

    symbol = TENCENT_SYMBOLS[product]
    errors: list[str] = []
    try:
        response = requests.get(
            "https://money.finance.sina.com.cn/quotes_service/api/json_v2.php"
            f"/CN_MarketData.getKLineData?symbol={symbol}&scale=240&ma=no&datalen=10000",
            timeout=_bounded_timeout(10),
            headers={"User-Agent": "Mozilla/5.0", "Referer": "https://finance.sina.com.cn/"},
        )
        response.raise_for_status()
        payload = response.json()
        rows = [
            {
                "date": item["day"],
                "open": float(item["open"]),
                "high": float(item["high"]),
                "low": float(item["low"]),
                "close": float(item["close"]),
                "volume": float(item["volume"]),
            }
            for item in payload
        ]
        if len(rows) >= 180:
            frame = pd.DataFrame(rows).assign(date=lambda x: pd.to_datetime(x["date"])).set_index("date").sort_index()
            frame.attrs["source"] = "Sina"
            return frame
        raise RuntimeError("Sina OHLCV不足180行")
    except Exception as exc:
        errors.append(f"Sina: {type(exc).__name__}: {exc}")
    try:
        payload = _request_json(
            "https://push2his.eastmoney.com/api/qt/stock/kline/get",
            {
                "secid": EASTMONEY_SECIDS[product],
                "klt": "101",
                "fqt": "0",
                "lmt": "10000",
                "end": "20500101",
                "fields1": "f1,f2,f3,f4,f5,f6",
                "fields2": "f51,f52,f53,f54,f55,f56,f57",
                "ut": "fa5fd1943c7b386f172d6893dbfba10b",
            },
        )
        klines = (payload.get("data") or {}).get("klines") or []
        rows = []
        for row in klines:
            parts = str(row).split(",")
            if len(parts) < 6:
                raise RuntimeError("Eastmoney OHLCV字段不足")
            rows.append(
                {
                    "date": parts[0], "open": float(parts[1]), "close": float(parts[2]),
                    "high": float(parts[3]), "low": float(parts[4]), "volume": float(parts[5]),
                }
            )
        if len(rows) >= 180:
            frame = pd.DataFrame(rows).assign(date=lambda x: pd.to_datetime(x["date"])).set_index("date").sort_index()
            frame.attrs["source"] = "Eastmoney"
            return frame
        raise RuntimeError("Eastmoney OHLCV不足180行")
    except Exception as exc:
        errors.append(f"Eastmoney: {type(exc).__name__}: {exc}")
    try:
        payload = _request_json(
            "https://web.ifzq.gtimg.cn/appstock/app/fqkline/get",
            {"param": f"{symbol},day,,,10000,qfq"},
        )
        node = ((payload.get("data") or {}).get(symbol) or {})
        raw_rows = node.get("qfqday") or node.get("day") or []
        rows = [
            {
                "date": item[0], "open": float(item[1]), "close": float(item[2]),
                "high": float(item[3]), "low": float(item[4]), "volume": float(item[5]),
            }
            for item in raw_rows if len(item) >= 6
        ]
        if len(rows) >= 180:
            frame = pd.DataFrame(rows).assign(date=lambda x: pd.to_datetime(x["date"])).set_index("date").sort_index()
            frame.attrs["source"] = "Tencent"
            return frame
        raise RuntimeError("Tencent OHLCV不足180行")
    except Exception as exc:
        errors.append(f"Tencent: {type(exc).__name__}: {exc}")
    raise RuntimeError(f"{product} OHLCV全部来源失败：{'；'.join(errors)}")


def _validated_price_history(
    product: str, history: pd.Series, clock: datetime
) -> pd.Series:
    result = pd.to_numeric(history.copy(), errors="coerce")
    index = pd.DatetimeIndex(pd.to_datetime(result.index, errors="raise"))
    if index.tz is not None:
        index = index.tz_convert(BEIJING).tz_localize(None)
    index = index.normalize()
    result.index = index
    replay_day = _HISTORICAL_REPLAY_DAY.get()
    if replay_day is not None:
        if replay_day != clock.date():
            raise RuntimeError(
                f"{product}历史重放日 {replay_day} 与运行时钟 {clock.date()} 不一致"
            )
        result = result.loc[result.index.date <= replay_day]
    if result.empty or result.index.has_duplicates or not result.index.is_monotonic_increasing:
        raise RuntimeError(f"{product} 价格历史日期为空、重复或乱序")
    values = result.to_numpy(dtype=float)
    if not np.isfinite(values).all() or (values <= 0).any():
        raise RuntimeError(f"{product} 价格历史含NaN、无穷值或非正价格，暂停生成信号")
    if result.index[-1].date() > clock.date():
        raise RuntimeError(
            f"{product} 价格历史日期 {result.index[-1].date()} 晚于北京时间 {clock.date()}"
        )
    expected = _latest_completed_exchange_day(clock)
    if result.index[-1].date() < expected:
        raise RuntimeError(
            f"{product} 价格历史已过期：最新 {result.index[-1].date()}，"
            f"至少应覆盖最近已完成交易日 {expected}；暂停生成信号"
        )
    return result


def live_proxy(product: str, clock: datetime | None = None) -> dict[str, Any]:
    clock = clock or _now_beijing()
    ohlcv: pd.DataFrame | None = None
    if product in {"IC", "IM"}:
        ohlcv = _validate_v13_ohlcv(product, fetch_ohlcv_history(product), clock)
        history = ohlcv["close"].copy()
    else:
        history = _validated_price_history(product, fetch_price_history(product), clock)
    replay_day = _HISTORICAL_REPLAY_DAY.get()
    if replay_day is not None:
        if history.index[-1].date() != replay_day:
            raise RuntimeError(
                f"{product}价格历史缺少待补账交易日 {replay_day} 的正式收盘"
            )
        live_price = float(history.iloc[-1])
        live_quote = {
            "price": live_price,
            "source": "指数公开日线历史收盘",
            "source_date": replay_day,
            "source_time": "15:00:00",
        }
    else:
        live_quote = fetch_live_price_quote(product)
        live_price = float(live_quote["price"])
        if not math.isfinite(live_price) or live_price <= 0:
            raise RuntimeError(f"{product} 实时报价含NaN、无穷值或非正价格")
    phase = _market_phase(clock)
    live_day = pd.Timestamp(clock.date())
    if replay_day is not None:
        pass
    elif (
        _is_exchange_trading_day(clock.date())
        and phase in {"集合竞价", "盘中", "午间休市", "收盘后"}
        and history.index[-1].date() < clock.date()
    ):
        if live_quote.get("source_date") != clock.date():
            raise RuntimeError(
                f"{product} 实时报价缺少{clock.date()}可验证时间戳，"
                "禁止把陈旧价格写成当日盘中价"
            )
        history.loc[live_day] = live_price
        if ohlcv is not None:
            previous_volume = float(ohlcv["volume"].iloc[-1])
            ohlcv.loc[live_day, ["open", "high", "low", "close", "volume"]] = [
                live_price, live_price, live_price, live_price, previous_volume
            ]
            ohlcv.loc[live_day, "realtime_volume_placeholder"] = True
    elif (
        _is_exchange_trading_day(clock.date())
        and phase in {"集合竞价", "盘中", "午间休市"}
        and history.index[-1].date() == clock.date()
    ):
        if live_quote.get("source_date") != clock.date():
            raise RuntimeError(f"{product} 当日未收盘K线缺少同日实时报价复核")
        history.iloc[-1] = live_price
        if ohlcv is not None:
            if len(ohlcv) < 2:
                raise RuntimeError(f"{product} OHLCV不足以冻结盘中成交量状态")
            previous_volume = float(ohlcv["volume"].iloc[-2])
            ohlcv.loc[live_day, ["open", "high", "low", "close", "volume"]] = [
                live_price, live_price, live_price, live_price, previous_volume
            ]
            ohlcv.loc[live_day, "realtime_volume_placeholder"] = True
    else:
        history.iloc[-1] = live_price
        if ohlcv is not None:
            ohlcv.loc[history.index[-1], "close"] = live_price
    history = history[~history.index.duplicated(keep="last")].sort_index()
    if not np.isfinite(history.to_numpy(dtype=float)).all() or (history <= 0).any():
        raise RuntimeError(f"{product} 合并实时价格后的历史数据无效")
    if len(history) < 135:
        raise RuntimeError(f"{product} 价格历史不足以计算1.3动量分袖")
    ratio = live_price / float(FROZEN[product]["price"])
    proxy_pb = float(FROZEN[product]["pb"]) * ratio
    proxy_pe = float(FROZEN[product]["pe"]) * ratio
    proxy_erp = 1.0 / proxy_pe - float(FROZEN[product]["gov10y"])
    score = valuation_score(proxy_pb, proxy_erp, float(FROZEN[product]["dividend"]))
    momentum = _momentum_120_at(history, -1)
    targets = (
        ic_targets(score, momentum) if product == "IC" else im_targets(score, momentum)
    )
    momentum_schedule = v13_momentum_schedule(product, history, ohlcv=ohlcv)
    current_momentum_weight = float(momentum_schedule["execution_weight"].iloc[-1])
    next_momentum_weight = float(momentum_schedule["signal_target"].iloc[-1])
    if not np.isfinite(current_momentum_weight):
        current_momentum_weight = float(V13_FROZEN[product]["momentum_weight"])
    prior_price = float(history.iloc[-2])
    prior_score = _proxy_score_for_price(product, prior_price)
    prior_mom120 = _momentum_120_at(history, -2)
    prior_targets = (
        ic_targets(prior_score, prior_mom120)
        if product == "IC"
        else im_targets(prior_score, prior_mom120)
    )
    grid_current, grid_target = _replay_v13_grid(product, history)
    if product == "IC":
        current_core_put = 0.5 * float(prior_targets["put_delta"])
        current_momentum_put = (
            0.5
            * current_momentum_weight
            * float(prior_targets["valuation_put_delta"])
        )
        current_put = current_core_put + current_momentum_put
        next_core_put = 0.5 * float(targets["put_delta"])
        next_momentum_put = (
            0.5
            * next_momentum_weight
            * float(targets["valuation_put_delta"])
        )
        next_put = next_core_put + next_momentum_put
        if current_momentum_weight <= 0:
            current_momentum_put_driver = "动量袖空仓，按规则Put归零"
        elif float(prior_targets["valuation_put_delta"]) > 0:
            current_momentum_put_driver = "估值档约束（动量袖不适用MOM120下限）"
        else:
            current_momentum_put_driver = (
                "估值处于基础观察档，目标0%；动量袖不适用MOM120下限"
            )
        if next_momentum_weight <= 0:
            momentum_put_driver = "动量袖空仓，按规则Put归零"
        elif float(targets["valuation_put_delta"]) > 0:
            momentum_put_driver = "估值档约束（动量袖不适用MOM120下限）"
        else:
            momentum_put_driver = (
                "估值处于基础观察档，目标0%；动量袖不适用MOM120下限"
            )
        option_state = {
            "v13_current_put_delta": current_put,
            "v13_current_core_put_delta": current_core_put,
            "v13_current_momentum_put_delta": current_momentum_put,
            "v13_put_target_delta": next_put,
            "v13_core_put_delta": next_core_put,
            "v13_momentum_put_delta": next_momentum_put,
            "valuation_tier": targets["valuation_tier"],
            "valuation_tier_label": targets["valuation_tier_label"],
            "valuation_put_delta": targets["valuation_put_delta"],
            "mom120_floor_delta": targets["mom120_floor_delta"],
            "current_core_put_driver": prior_targets["put_driver"],
            "current_momentum_put_driver": current_momentum_put_driver,
            "core_put_driver": targets["put_driver"],
            "momentum_put_driver": momentum_put_driver,
        }
    else:
        option_state = {
            "v13_current_parent_puts": int(prior_targets["puts_per_core"]),
            "v13_parent_puts_per_full_core": int(targets["puts_per_core"]),
            "v13_current_put_qty_normalized": 0.5
            * int(prior_targets["puts_per_core"]),
            "v13_put_target_qty_normalized": 0.5
            * int(targets["puts_per_core"]),
            "absolute_valuation_tier": targets["absolute_valuation_tier"],
            "absolute_valuation_tier_label": targets[
                "absolute_valuation_tier_label"
            ],
            "relative_valuation_tier": targets["relative_valuation_tier"],
            "relative_valuation_tier_label": targets[
                "relative_valuation_tier_label"
            ],
            "valuation_puts_per_full_core": targets[
                "valuation_puts_per_full_core"
            ],
            "mom120_floor_puts_per_full_core": targets[
                "mom120_floor_puts_per_full_core"
            ],
            "core_put_driver": targets["put_driver"],
        }
    return {
        "price": live_price,
        "live_price_source": live_quote.get("source", "未知"),
        "live_price_source_date": live_quote.get("source_date"),
        "live_price_source_time": live_quote.get("source_time"),
        "proxy_pb": proxy_pb,
        "proxy_pe": proxy_pe,
        "proxy_erp": proxy_erp,
        "score": score,
        "momentum_120": momentum,
        "history_date": history.index[-1].date(),
        "momentum_score": float(momentum_schedule["momentum_score"].iloc[-1]),
        "momentum_abs20": float(momentum_schedule["abs20"].iloc[-1]),
        "momentum_volume_ratio": float(momentum_schedule["volume_ratio"].iloc[-1]),
        "momentum_volume_pass": bool(momentum_schedule["volume_pass"].iloc[-1]),
        "momentum_volume_placeholder": bool(momentum_schedule["volume_placeholder"].iloc[-1]),
        "momentum_score_hot": bool(momentum_schedule["score_hot_signal"].iloc[-1]),
        "momentum_base_nav": float(momentum_schedule["base_nav_for_dd"].iloc[-1]),
        "momentum_base_dd": float(momentum_schedule["base_dd_for_gate"].iloc[-1]),
        "momentum_nav_defense": bool(momentum_schedule["nav_decay_signal"].iloc[-1]),
        "momentum_ohlcv_source": (ohlcv.attrs.get("source", "未知") if ohlcv is not None else None),
        "momentum_current_weight": current_momentum_weight,
        "momentum_next_weight": next_momentum_weight,
        "momentum_signal_date": history.index[-1].date(),
        "momentum_current_source_date": history.index[-2].date(),
        "grid_current_units": grid_current,
        "grid_target_units": grid_target,
        **option_state,
        **targets,
    }


def _numeric_frame(
    frame: pd.DataFrame, skip: tuple[str, ...] = ("instrument",)
) -> pd.DataFrame:
    result = frame.copy()
    for column in result.columns:
        if column not in skip:
            result[column] = pd.to_numeric(result[column], errors="coerce")
    return result


def _response_with_size_limit(response: Any, label: str) -> bytes:
    declared = response.headers.get("Content-Length")
    if declared and int(declared) > MAX_QUOTE_RESPONSE_BYTES:
        raise RuntimeError(f"{label}响应声明大小超过{MAX_QUOTE_RESPONSE_BYTES}字节")
    content = response.content
    if len(content) > MAX_QUOTE_RESPONSE_BYTES:
        raise RuntimeError(f"{label}响应大小超过{MAX_QUOTE_RESPONSE_BYTES}字节")
    return content


def _http_source_stamp(response: Any, label: str) -> datetime:
    raw = response.headers.get("Last-Modified")
    if not raw:
        raise RuntimeError(f"{label}缺少可验证的Last-Modified行情时间")
    try:
        stamp = parsedate_to_datetime(raw)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"{label}的Last-Modified行情时间非法") from exc
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=ZoneInfo("UTC"))
    return stamp.astimezone(BEIJING)


def _validate_quote_frame(
    frame: pd.DataFrame,
    product: str,
    clock: datetime,
    source: str,
) -> pd.DataFrame:
    required = {"instrument", "lastprice", "volume", "position", "source_date"}
    missing = sorted(required.difference(frame.columns))
    if missing:
        raise RuntimeError(f"{source} {product}行情缺少标准列: {','.join(missing)}")
    result = frame.copy()
    result["instrument"] = result["instrument"].astype(str).str.strip().str.upper()
    pattern = rf"{product}\d{{4}}" if product in {"IC", "IM"} else r"MO\d{4}-[CP]-\d+"
    if result.empty:
        raise RuntimeError(f"{source} {product}没有格式有效的合约")
    if not bool(result["instrument"].str.fullmatch(pattern).all()):
        invalid = result.loc[
            ~result["instrument"].str.fullmatch(pattern), "instrument"
        ].iloc[0]
        raise RuntimeError(f"{source} {product}含非法合约代码: {invalid}")
    if result["instrument"].duplicated().any():
        duplicate = result.loc[result["instrument"].duplicated(), "instrument"].iloc[0]
        raise RuntimeError(f"{source} {product}行情包含重复合约: {duplicate}")
    # Source dates belong to the raw listing rows, not only to rows that happen
    # to have a positive trade.  Validate them before filtering no-trade rows so
    # a future/stale dated invalid quote cannot disappear silently.
    try:
        result["source_date"] = result["source_date"].map(
            lambda value: value
            if isinstance(value, date) and not isinstance(value, datetime)
            else date.fromisoformat(str(value)[:10])
        )
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"{source} {product}含非法行情日期") from exc
    source_days = sorted(set(result["source_date"]))
    if len(source_days) != 1:
        raise RuntimeError(f"{source} {product}行情日期不一致: {source_days}")
    source_day = source_days[0]
    expected = _latest_completed_exchange_day(clock)
    if source_day > clock.date():
        raise RuntimeError(f"{source} {product}行情日期 {source_day} 晚于北京时间")
    if source_day < expected:
        raise RuntimeError(
            f"{source} {product}行情已过期：最新 {source_day}，至少应覆盖 {expected}"
        )
    listing_frame = result[["instrument"]].copy()
    for column in ("lastprice", "volume", "position", "bprice", "sprice"):
        if column in result:
            result[column] = pd.to_numeric(result[column], errors="coerce")
    valid = (
        np.isfinite(result["lastprice"].to_numpy(dtype=float))
        & result["lastprice"].gt(0)
        & np.isfinite(result["volume"].to_numpy(dtype=float))
        & result["volume"].ge(0)
        & np.isfinite(result["position"].to_numpy(dtype=float))
        & result["position"].ge(0)
    )
    result = result[valid].copy()
    if result.empty:
        raise RuntimeError(f"{source} {product}没有有限正价行情")
    for column in ("bprice", "sprice"):
        if column in result:
            finite_or_missing = result[column].isna() | (
                np.isfinite(result[column].fillna(0).to_numpy(dtype=float))
                & result[column].fillna(0).ge(0)
            )
            if not bool(finite_or_missing.all()):
                raise RuntimeError(f"{source} {product}含非法买卖报价")
    result["source"] = source
    result = result.sort_values("instrument").reset_index(drop=True)
    if product in {"IC", "IM"}:
        _validate_complete_future_structure(
            result,
            product,
            source_day,
            source,
            set(listing_frame["instrument"]),
        )
    else:
        _validate_complete_mo_chain(result, source_day, source, listing_frame)
    result.attrs.update(
        source=source,
        source_date=source_day,
        source_failures=[],
        source_audit=[],
        listed_instruments=sorted(set(listing_frame["instrument"])),
        listed_mo_months=(
            sorted(
                set(
                    listing_frame["instrument"].str.extract(
                        r"^(MO\d{4})", expand=False
                    )
                )
            )
            if product == "MO"
            else []
        ),
    )
    return result


def _month_after(year: int, month: int, offset: int = 1) -> tuple[int, int]:
    ordinal = year * 12 + (month - 1) + offset
    return ordinal // 12, ordinal % 12 + 1


def _front_listed_month(as_of: date) -> tuple[int, int]:
    year, month = as_of.year, as_of.month
    if as_of > _third_friday(year, month):
        return _month_after(year, month)
    return year, month


def _following_quarter_months(
    after_year: int,
    after_month: int,
    count: int,
) -> list[tuple[int, int]]:
    result: list[tuple[int, int]] = []
    year, month = after_year, after_month
    while len(result) < count:
        year, month = _month_after(year, month)
        if month in {3, 6, 9, 12}:
            result.append((year, month))
    return result


def _expected_future_contracts(product: str, as_of: date) -> set[str]:
    front = _front_listed_month(as_of)
    next_month = _month_after(*front)
    months = [front, next_month, *_following_quarter_months(*next_month, 2)]
    return {f"{product}{year % 100:02d}{month:02d}" for year, month in months}


def _expected_mo_months(as_of: date) -> set[str]:
    front = _front_listed_month(as_of)
    next_one = _month_after(*front)
    next_two = _month_after(*front, 2)
    months = [front, next_one, next_two, *_following_quarter_months(*next_two, 3)]
    return {f"MO{year % 100:02d}{month:02d}" for year, month in months}


def _validate_complete_future_structure(
    frame: pd.DataFrame,
    product: str,
    as_of: date,
    source: str,
    listed_instruments: set[str] | None = None,
) -> None:
    actual = listed_instruments or set(frame["instrument"])
    expected = _expected_future_contracts(product, as_of)
    if actual != expected:
        missing = sorted(expected - actual)
        extra = sorted(actual - expected)
        raise RuntimeError(
            f"{source} {product}挂牌结构不完整：as-of {as_of}应为"
            f"{sorted(expected)}，缺失{missing}，多余{extra}"
        )
    front_year, front_month = _front_listed_month(as_of)
    front_contract = f"{product}{front_year % 100:02d}{front_month:02d}"
    if front_contract not in set(frame["instrument"]):
        raise RuntimeError(
            f"{source} {product}最近月 {front_contract} 缺少有限正价，"
            "禁止用远月替代活跃合约"
        )
    nearest_days = min(
        abs((_third_friday(*_contract_month(contract)) - as_of).days)
        for contract in actual
    )
    if nearest_days > 45:
        raise RuntimeError(
            f"{source} {product}最近挂牌月距源日期{nearest_days}天，拒绝陈旧合约结构"
        )


def _mo_month_set(frame: pd.DataFrame) -> set[str]:
    listed = frame.attrs.get("listed_mo_months")
    if listed:
        return set(listed) | set(
            frame["instrument"].str.extract(r"^(MO\d{4})", expand=False)
        )
    return set(frame["instrument"].str.extract(r"^(MO\d{4})", expand=False))


def _validate_complete_mo_chain(
    frame: pd.DataFrame,
    as_of: date,
    source: str,
    listing_frame: pd.DataFrame | None = None,
) -> None:
    structure = listing_frame if listing_frame is not None else frame[["instrument"]]
    parsed = structure["instrument"].str.extract(
        r"MO(\d{2})(\d{2})-([CP])-(\d+)"
    )
    expiries = [
        _third_friday(2000 + int(year), int(month))
        for year, month in zip(parsed[0], parsed[1], strict=True)
    ]
    work = structure.assign(
        expiry=expiries,
        option_type=parsed[2].to_numpy(),
        strike=pd.to_numeric(parsed[3], errors="coerce").to_numpy(),
    )
    actual_months = set(
        structure["instrument"].str.extract(r"^(MO\d{4})", expand=False)
    )
    expected_months = _expected_mo_months(as_of)
    if actual_months != expected_months:
        missing = sorted(expected_months - actual_months)
        extra = sorted(actual_months - expected_months)
        raise RuntimeError(
            f"{source} MO备用链不完整：as-of {as_of}应挂牌"
            f"{sorted(expected_months)}，缺失{missing}，多余{extra}"
        )
    live = work[work["expiry"].ge(as_of)]
    live_expiries = sorted(set(live["expiry"]))
    for expiry in live_expiries:
        month = live[live["expiry"].eq(expiry)]
        calls = set(month.loc[month["option_type"].eq("C"), "strike"])
        puts = set(month.loc[month["option_type"].eq("P"), "strike"])
        if len(calls & puts) < 3:
            raise RuntimeError(
                f"{source} MO备用链不完整：{expiry} Call/Put共同有效行权价少于3个"
            )


def _fetch_cffex_official_quotes(product: str, clock: datetime) -> pd.DataFrame:
    if product not in {"IC", "IM", "MO"}:
        raise ValueError(f"不支持的中金所品种: {product}")
    response = requests.get(
        f"https://www.cffex.com.cn/quote_{product}.txt",
        timeout=_bounded_timeout(QUOTE_OFFICIAL_SOURCE_BUDGET_SECONDS),
        headers={
            "User-Agent": "Mozilla/5.0 POE-IC-IM-Research/1.0",
            "Cache-Control": "no-cache",
            "Pragma": "no-cache",
        },
    )
    response.raise_for_status()
    stamp = _http_source_stamp(response, f"中金所官方 {product}")
    content = _response_with_size_limit(response, f"中金所官方 {product}")
    lines = content.decode(response.encoding or "utf-8", errors="replace").splitlines()
    header_index = next(
        (
            index
            for index, line in enumerate(lines)
            if line.lstrip("\ufeff").lower().startswith("instrument,")
        ),
        None,
    )
    if header_index is None:
        raise RuntimeError(f"中金所 {product} 延时行情缺少CSV表头")
    frame = pd.read_csv(io.StringIO("\n".join(lines[header_index:])))
    if "instrument" not in frame or frame.empty:
        raise RuntimeError(f"中金所 {product} 延时行情为空")
    frame["instrument"] = frame["instrument"].astype(str).str.strip()
    frame = _numeric_frame(frame)
    frame["source_date"] = stamp.date()
    frame["source_time"] = stamp.strftime("%H:%M:%S")
    return _validate_quote_frame(frame, product, clock, "中金所官方")


def _fetch_sina_future_quotes(product: str, clock: datetime) -> pd.DataFrame:
    node = {"IC": "zzgz_qh", "IM": "im_qh"}[product]
    response = requests.get(
        "https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/"
        "Market_Center.getHQFuturesData",
        params={
            "page": 1,
            "num": 40,
            "sort": "position",
            "asc": 0,
            "node": node,
            "base": "futures",
        },
        timeout=_bounded_timeout(6),
        headers={
            "User-Agent": "Mozilla/5.0 POE-IC-IM-Research/1.0",
            "Referer": "https://vip.stock.finance.sina.com.cn/",
            "Cache-Control": "no-cache",
        },
    )
    response.raise_for_status()
    _response_with_size_limit(response, f"新浪财经 {product}")
    payload = response.json()
    if not isinstance(payload, list) or not payload:
        raise RuntimeError(f"新浪财经 {product}行情为空")
    rows = []
    for item in payload:
        instrument = str(item.get("symbol", "")).upper()
        if not re.fullmatch(rf"{product}\d{{4}}", instrument):
            continue
        rows.append(
            {
                "instrument": instrument,
                "openprice": item.get("open"),
                "highest": item.get("high"),
                "lowest": item.get("low"),
                "lastprice": item.get("trade"),
                "bprice": item.get("bidprice1"),
                "sprice": item.get("askprice1"),
                "volume": item.get("volume"),
                "position": item.get("position"),
                "source_date": item.get("tradedate"),
                "source_time": item.get("ticktime"),
            }
        )
    frame = pd.DataFrame(rows)
    if not frame.empty:
        parsed_days = pd.to_datetime(frame["source_date"], errors="coerce").dt.date
        valid_days = [day for day in parsed_days if isinstance(day, date)]
        if valid_days:
            latest_day = max(valid_days)
            frame = frame.loc[parsed_days.eq(latest_day)].copy()
    return _validate_quote_frame(frame, product, clock, "新浪财经")


