def fetch_sse_510500_quote() -> dict[str, Any]:
    payload = _sse_quote_json(
        "v1/sh1/list/self/510500",
        {
            "select": "code,cpxxextendname,last,change,chg_rate,amp_rate,volume,amount,prev_close"
        },
    )
    rows = payload.get("list") or []
    if not rows:
        raise RuntimeError("上交所未返回有效510500ETF行情")
    last = float(rows[0][2])
    prev_close = float(rows[0][8])
    if not all(math.isfinite(value) and value > 0 for value in (last, prev_close)):
        raise RuntimeError("上交所510500ETF行情含NaN、无穷值或非正价格")
    return {
        "date": str(payload.get("date", "")),
        "time": str(payload.get("time", "")).zfill(6),
        "last": last,
        "prev_close": prev_close,
    }


def fetch_sse_510500_chain(expiry_ym: str) -> tuple[pd.DataFrame, dict[str, str]]:
    match = re.fullmatch(r"(20)?(\d{2})(\d{2})", str(expiry_ym))
    if not match:
        raise ValueError(f"非法ETF期权月份: {expiry_ym}")
    yy, month = match.group(2), match.group(3)
    payload = _sse_quote_json(
        f"v1/sho/list/tstyle/510500_{month}",
        {
            "select": "contractid,last,chg_rate,presetpx,exepx",
            "order": "contractid,ase",
        },
    )
    rows = payload.get("list") or []
    columns = ["contract", "last", "chg_rate", "pre_settle", "strike"]
    frame = (
        pd.DataFrame(rows, columns=columns) if rows else pd.DataFrame(columns=columns)
    )
    if not frame.empty:
        frame = _numeric_frame(frame, skip=("contract",))
        frame["contract"] = frame["contract"].astype(str)
        frame = frame[
            frame["contract"].str.contains(rf"510500[CP]{yy}{month}", regex=True)
        ].copy()
    return frame, {
        "date": str(payload.get("date", "")),
        "time": str(payload.get("time", "")).zfill(6),
    }


def fetch_sse_510500_expiries() -> list[str]:
    payload = _sse_quote_json(
        "v1/sho/list/exchange/stockexpire",
        {"select": "stockid,expiremonth"},
    )
    months: set[str] = set()
    for row in payload.get("list") or []:
        if len(row) < 2 or str(row[0]) != "510500":
            continue
        value = str(row[1]).strip()
        if not re.fullmatch(r"20\d{4}", value):
            continue
        if 1 <= int(value[4:]) <= 12:
            months.add(value)
    ordered_months = sorted(months)
    if not ordered_months:
        raise RuntimeError("上交所未返回510500ETF期权挂牌月份")
    return ordered_months


def fetch_sse_510500_historical_quote(day: date) -> dict[str, Any]:
    payload = _request_json(
        "https://web.ifzq.gtimg.cn/appstock/app/kline/kline",
        {"param": "sh510500,day,,,260"},
    )
    rows = ((payload.get("data") or {}).get("sh510500") or {}).get("day") or []
    points = {
        date.fromisoformat(str(row[0])): float(row[2])
        for row in rows
        if len(row) >= 3
    }
    if day not in points:
        raise RuntimeError(f"上交所510500ETF历史日线缺少 {day} 收盘")
    ordered = sorted(points)
    location = ordered.index(day)
    previous = points[ordered[location - 1]] if location else points[day]
    return {
        "date": day.isoformat(),
        "time": "150000",
        "last": float(points[day]),
        "prev_close": float(previous),
    }


def fetch_sse_existing_put_historical_quote(
    contract: str, security_id: str, day: date
) -> tuple[pd.DataFrame, dict[str, str]]:
    closes = fetch_sina_option_closes(security_id)
    stamp = pd.Timestamp(day)
    if stamp not in closes.index:
        raise RuntimeError(f"上交所期权 {contract} 历史日线缺少 {day} 收盘")
    match = re.fullmatch(r"510500P\d{4}M(\d{5})", contract)
    if not match:
        raise RuntimeError(f"无法解析IC Put行权价: {contract}")
    frame = pd.DataFrame(
        [
            {
                "contract": contract,
                "last": float(closes.loc[stamp]),
                "strike": float(match.group(1)) / 1000.0,
            }
        ]
    )
    return frame, {"date": day.isoformat(), "time": "150000"}


def _is_exchange_trading_day(day: date) -> bool:
    if day.weekday() >= 5:
        return False
    if day.year not in _OFFICIAL_EXCHANGE_CALENDAR_YEARS:
        return True
    return day not in _EXCHANGE_CLOSURES


def _require_official_exchange_calendar(day: date, label: str) -> None:
    if day.year not in _OFFICIAL_EXCHANGE_CALENDAR_YEARS:
        covered = "/".join(str(year) for year in sorted(_OFFICIAL_EXCHANGE_CALENDAR_YEARS))
        raise RuntimeError(
            f"{label}需要{day.year}年官方交易日历，但脚本仅覆盖{covered}年；"
            "暂停实时新鲜度判定和新增信号"
        )


def _roll_backward_exchange_day(
    day: date,
    *,
    require_official: bool = False,
) -> date:
    candidate = day
    while not _is_exchange_trading_day(candidate):
        candidate -= timedelta(days=1)
        if require_official:
            _require_official_exchange_calendar(candidate, "最近已完成交易日判定")
    return candidate


def _latest_completed_exchange_day(clock: datetime) -> date:
    _require_official_exchange_calendar(clock.date(), "实时行情新鲜度校验")
    phase = _market_phase(clock)
    if _is_exchange_trading_day(clock.date()) and phase == "收盘后":
        return clock.date()
    prior_day = clock.date() - timedelta(days=1)
    _require_official_exchange_calendar(prior_day, "最近已完成交易日判定")
    return _roll_backward_exchange_day(prior_day, require_official=True)


def _roll_forward_exchange_day(day: date) -> date:
    candidate = day
    while not _is_exchange_trading_day(candidate):
        candidate += timedelta(days=1)
    return candidate


def _third_friday(year: int, month: int) -> date:
    weeks = month_calendar.monthcalendar(year, month)
    fridays = [
        week[month_calendar.FRIDAY] for week in weeks if week[month_calendar.FRIDAY]
    ]
    return _roll_forward_exchange_day(date(year, month, fridays[2]))


def _fourth_wednesday(year: int, month: int) -> date:
    weeks = month_calendar.monthcalendar(year, month)
    days = [
        week[month_calendar.WEDNESDAY]
        for week in weeks
        if week[month_calendar.WEDNESDAY]
    ]
    return _roll_forward_exchange_day(date(year, month, days[3]))


def _contract_month(contract: str) -> tuple[int, int]:
    match = re.fullmatch(
        r"(?:(?:IC|IM)(\d{2})(\d{2})|MO(\d{2})(\d{2})-[CP]-\d+)",
        str(contract).upper(),
    )
    if not match:
        raise ValueError(f"无法识别合约月份: {contract}")
    year = match.group(1) or match.group(3)
    month = match.group(2) or match.group(4)
    return 2000 + int(year), int(month)


def select_active_future(product: str, quotes: pd.DataFrame, today: date) -> pd.Series:
    if "lastprice" not in quotes:
        raise RuntimeError(f"{product} 延时行情缺少 lastprice")
    candidates = quotes[quotes["instrument"].str.fullmatch(rf"{product}\d{{4}}")].copy()
    candidates = candidates[
        np.isfinite(candidates["lastprice"].to_numpy(dtype=float))
        & candidates["lastprice"].gt(0)
    ]
    if candidates.empty:
        raise RuntimeError(f"{product} 无可用期货合约")
    candidates["expiry"] = candidates["instrument"].map(
        lambda value: _third_friday(*_contract_month(value))
    )
    eligible = candidates[candidates["expiry"].ge(today)].sort_values("expiry")
    if eligible.empty:
        latest = candidates["expiry"].max()
        raise RuntimeError(
            f"{product} 行情中的期货合约均已到期（最晚规则到期日 {latest}）"
        )
    return eligible.iloc[0]


def _next_listed_future_contract(
    product: str,
    quotes: pd.DataFrame,
    active_expiry: date,
) -> str:
    listed = {
        str(contract)
        for contract in quotes.attrs.get(
            "listed_instruments", quotes["instrument"].tolist()
        )
        if re.fullmatch(rf"{product}\d{{4}}", str(contract))
    }
    later = sorted(
        (
            contract
            for contract in listed
            if _third_friday(*_contract_month(contract)) > active_expiry
        ),
        key=lambda contract: _third_friday(*_contract_month(contract)),
    )
    return later[0] if later else ""


def _require_listed_future_quote(
    product: str,
    quotes: pd.DataFrame,
    contract: str,
) -> pd.Series:
    rows = quotes[quotes["instrument"].eq(contract)]
    if rows.empty:
        raise RuntimeError(
            f"{product}规则下一挂牌合约 {contract} 缺少有限正价，禁止跳到更远月份"
        )
    return rows.iloc[0]


def _quote_row(frame: pd.DataFrame, contract: str) -> pd.Series | None:
    rows = (
        frame[frame["instrument"].eq(contract)]
        if "instrument" in frame
        else frame[frame["contract"].eq(contract)]
    )
    return rows.iloc[0] if len(rows) else None


def _normal_cdf(value: float) -> float:
    return 0.5 * (1.0 + math.erf(value / math.sqrt(2.0)))


def _bs_price_delta(
    option_type: str,
    spot: float,
    strike: float,
    rate: float,
    dividend: float,
    sigma: float,
    years: float,
) -> tuple[float, float]:
    if min(spot, strike, sigma, years) <= 0:
        raise ValueError("Black-Scholes 输入必须为正")
    root_t = math.sqrt(years)
    d1 = (math.log(spot / strike) + (rate - dividend + 0.5 * sigma * sigma) * years) / (
        sigma * root_t
    )
    d2 = d1 - sigma * root_t
    if option_type == "C":
        price = spot * math.exp(-dividend * years) * _normal_cdf(
            d1
        ) - strike * math.exp(-rate * years) * _normal_cdf(d2)
        delta = math.exp(-dividend * years) * _normal_cdf(d1)
    else:
        price = strike * math.exp(-rate * years) * _normal_cdf(-d2) - spot * math.exp(
            -dividend * years
        ) * _normal_cdf(-d1)
        delta = -math.exp(-dividend * years) * _normal_cdf(-d1)
    return price, delta


def _implied_volatility(
    option_type: str,
    market_price: float,
    spot: float,
    strike: float,
    rate: float,
    dividend: float,
    years: float,
) -> float | None:
    if min(market_price, spot, strike, years) <= 0:
        return None
    low, high = 0.001, 5.0
    low_price = _bs_price_delta(option_type, spot, strike, rate, dividend, low, years)[
        0
    ]
    high_price = _bs_price_delta(
        option_type, spot, strike, rate, dividend, high, years
    )[0]
    if market_price < low_price - 1e-8 or market_price > high_price + 1e-8:
        return None
    for _ in range(80):
        middle = (low + high) / 2.0
        price = _bs_price_delta(
            option_type, spot, strike, rate, dividend, middle, years
        )[0]
        if price < market_price:
            low = middle
        else:
            high = middle
    return (low + high) / 2.0


def _format_market(contract: str, row: pd.Series | None) -> str:
    if row is None:
        return f"`{contract}`（当前行情缺失）"
    last = float(row.get("lastprice", row.get("last", np.nan)))
    bid = float(row.get("bprice", np.nan))
    ask = float(row.get("sprice", np.nan))
    text = f"`{contract}`，最新 {last:.4g}"
    if np.isfinite(bid) and bid >= 0 and np.isfinite(ask) and ask >= 0:
        text += f"，买/卖 {bid:.4g}/{ask:.4g}"
    return text


def _require_existing_leg_quote(
    leg: str,
    contract: str,
    row: pd.Series | None,
    action: str,
) -> None:
    state_change = action in {
        "ROLL",
        "RESIZE_OR_ROLL",
        "CLOSE_CALL",
        "RESCUE_NEXT_LISTED",
    }
    if not state_change:
        return
    if row is None:
        raise RuntimeError(f"{leg}旧腿 {contract} 缺少有效报价，禁止继续{action}")
    last = float(row.get("lastprice", row.get("last", np.nan)))
    if not np.isfinite(last) or last <= 0:
        raise RuntimeError(f"{leg}旧腿 {contract} 缺少有限正价，禁止继续{action}")
    if "position" in row.index:
        position = float(row.get("position", np.nan))
        if not np.isfinite(position) or position <= 0:
            raise RuntimeError(f"{leg}旧腿 {contract} 缺少正持仓量，禁止继续{action}")
    if "bprice" in row.index and "sprice" in row.index:
        bid = float(row.get("bprice", np.nan))
        ask = float(row.get("sprice", np.nan))
        if not all(np.isfinite(value) and value > 0 for value in (bid, ask)):
            raise RuntimeError(f"{leg}旧腿 {contract} 缺少双边有效报价，禁止继续{action}")


def _format_quote_number(value: Any, decimals: int = 2) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "缺失"
    if not np.isfinite(number) or number < 0:
        return "缺失"
    return f"{number:.{decimals}f}"


def _grid_target(product: str, live: dict[str, Any]) -> tuple[int, str]:
    current = int(round(float(live["grid_current_units"])))
    target = int(round(float(live["grid_target_units"])))
    if target > current:
        return target, "ADD_GRID"
    if target < current:
        return target, "EXIT_GRID"
    return current, "HOLD"


def _apportion_integer_quantity(
    total: int, raw_parts: dict[str, float]
) -> dict[str, int]:
    """Split an already-rounded total without creating phantom contracts."""
    if total < 0 or any(value < 0 for value in raw_parts.values()):
        raise ValueError("Put张数及分袖原始张数不得为负")
    result = {name: math.floor(value) for name, value in raw_parts.items()}
    remaining = total - sum(result.values())
    if remaining < 0:
        raise ValueError("Put整数总张数小于各分袖向下取整之和")
    ranked = sorted(
        raw_parts,
        key=lambda name: (-(raw_parts[name] - math.floor(raw_parts[name])), name),
    )
    positive = [name for name in ranked if raw_parts[name] > 0]
    if remaining and not positive:
        raise ValueError("Put总张数为正但所有分袖贡献均为零")
    for index in range(remaining):
        result[positive[index % len(positive)]] += 1
    return result


def _ic_put_quantity_breakdown(
    full_equivalent: int,
    absolute_delta: float,
    core_delta: float,
    momentum_delta: float,
    total_qty: int | None = None,
) -> dict[str, float | int]:
    if absolute_delta <= 1e-8:
        raise ValueError("IC Put绝对Delta必须大于0")
    raw_parts = {
        "core": full_equivalent * core_delta / absolute_delta,
        "momentum": full_equivalent * momentum_delta / absolute_delta,
    }
    combined_raw = sum(raw_parts.values())
    if total_qty is None:
        total_qty = max(1, round(combined_raw)) if combined_raw > 0 else 0
    split = _apportion_integer_quantity(total_qty, raw_parts)
    return {
        "total_raw": combined_raw,
        "total": total_qty,
        "core_raw": raw_parts["core"],
        "core": split["core"],
        "momentum_raw": raw_parts["momentum"],
        "momentum": split["momentum"],
        "grid": 0,
    }


def _size_existing_ic_put(
    contract: str,
    quote: pd.Series,
    today: date,
    etf_price: float,
    future_price: float,
    current_total_qty: int,
    current_core_delta: float,
    current_momentum_delta: float,
    target_core_delta: float,
    target_momentum_delta: float,
) -> dict[str, Any]:
    """Resize an already-audited IC Put without silently reselecting its contract."""
    match = re.fullmatch(r"510500P(\d{2})(\d{2})M(\d{5})", contract)
    if not match:
        raise RuntimeError(f"无法解析IC Put月份或行权价: {contract}")
    expiry = _fourth_wednesday(2000 + int(match.group(1)), int(match.group(2)))
    strike = float(match.group(3)) / 1000.0
    market_price = float(quote.get("last", np.nan))
    years = max((expiry - today).days, 1) / 365.0
    iv = _implied_volatility(
        "P",
        market_price,
        etf_price,
        strike,
        float(FROZEN["IC"]["gov10y"]),
        float(FROZEN["IC"]["dividend"]),
        years,
    )
    if iv is None:
        raise RuntimeError(f"IC既有Put {contract} 无法由有效价格反解IV，禁止自动改张")
    absolute_delta = abs(
        _bs_price_delta(
            "P",
            etf_price,
            strike,
            float(FROZEN["IC"]["gov10y"]),
            float(FROZEN["IC"]["dividend"]),
            iv,
            years,
        )[1]
    )
    if absolute_delta <= 1e-8:
        raise RuntimeError(f"IC既有Put {contract} 的绝对Delta无效，禁止自动改张")
    full_equivalent = max(1, round(future_price * 200.0 / (etf_price * 10_000.0)))
    current_breakdown = _ic_put_quantity_breakdown(
        full_equivalent,
        absolute_delta,
        current_core_delta,
        current_momentum_delta,
        current_total_qty,
    )
    target_total_delta = target_core_delta + target_momentum_delta
    target_total_qty = (
        max(1, round(full_equivalent * target_total_delta / absolute_delta))
        if target_total_delta > 0
        else 0
    )
    target_breakdown = _ic_put_quantity_breakdown(
        full_equivalent,
        absolute_delta,
        target_core_delta,
        target_momentum_delta,
        target_total_qty,
    )
    return {
        "put_sizing_future_price": future_price,
        "put_sizing_future_multiplier": 200,
        "put_sizing_future_notional": future_price * 200.0,
        "put_sizing_etf_price": etf_price,
        "put_sizing_option_multiplier": 10_000,
        "put_sizing_etf_option_notional": etf_price * 10_000.0,
        "put_sizing_full_equivalent_contracts": full_equivalent,
        "put_sizing_target_delta": target_total_delta,
        "put_sizing_option_abs_delta": absolute_delta,
        "put_sizing_raw_qty": full_equivalent * target_total_delta / absolute_delta,
        "put_sizing_rounded_qty": target_total_qty,
        "put_current_total_qty": int(current_breakdown["total"]),
        "put_current_core_qty": int(current_breakdown["core"]),
        "put_current_momentum_qty": int(current_breakdown["momentum"]),
        "put_current_grid_qty": 0,
        "put_target_total_qty": int(target_breakdown["total"]),
        "put_target_core_qty": int(target_breakdown["core"]),
        "put_target_momentum_qty": int(target_breakdown["momentum"]),
        "put_target_grid_qty": 0,
        "put_sizing_iv": iv,
        "put_sizing_expiry": expiry,
        "put_sizing_strike": strike,
        "put_sizing_signal_date": today,
    }


def select_ic_put_for_reset(
    today: date,
    etf_price: float,
    future_price: float,
    target_delta: float,
) -> dict[str, Any]:
    if not 0.0 <= target_delta <= 1.0:
        raise ValueError(f"IC Put目标绝对Delta超出[0, 1]: {target_delta}")
    if math.isclose(target_delta, 0.0, rel_tol=0.0, abs_tol=1e-12):
        return {
            "contract": None,
            "quote": None,
            "expiry": None,
            "strike": None,
            "qty": 0,
            "iv": None,
            "absolute_delta": None,
            "stamp": None,
        }
    target_day = (pd.Timestamp(today) + pd.DateOffset(months=3)).date()
    months = fetch_sse_510500_expiries()
    candidates: list[tuple[str, date]] = []
    for value in months:
        expiry = _fourth_wednesday(int(value[:4]), int(value[4:]))
        if expiry > today:
            candidates.append((value, expiry))
    if not candidates:
        raise RuntimeError("没有未来510500ETF Put挂牌月份")
    month, expiry = min(
        candidates, key=lambda item: (abs((item[1] - target_day).days), item[1])
    )
    chain, stamp = fetch_sse_510500_chain(month[2:])
    puts = chain[
        chain["contract"].str.contains(rf"510500P{month[2:]}M", regex=True)
        & chain["last"].gt(0)
    ].copy()
    if puts.empty:
        raise RuntimeError(f"{month} 没有可用标准510500ETF Put")
    puts["strike_error"] = (puts["strike"] - 0.95 * etf_price).abs()
    selected = puts.sort_values(["strike_error", "contract"]).iloc[0]
    years = max((expiry - today).days, 1) / 365.0
    iv = _implied_volatility(
        "P",
        float(selected["last"]),
        etf_price,
        float(selected["strike"]),
        float(FROZEN["IC"]["gov10y"]),
        float(FROZEN["IC"]["dividend"]),
        years,
    )
    absolute_delta = None
    qty = None
    if iv is not None:
        absolute_delta = abs(
            _bs_price_delta(
                "P",
                etf_price,
                float(selected["strike"]),
                float(FROZEN["IC"]["gov10y"]),
                float(FROZEN["IC"]["dividend"]),
                iv,
                years,
            )[1]
        )
        full_qty = max(1, round(future_price * 200.0 / (etf_price * 10_000.0)))
        qty = (
            max(1, round(full_qty * target_delta / absolute_delta))
            if absolute_delta > 1e-8
            else None
        )
    return {
        "contract": str(selected["contract"]),
        "security_id": fetch_sina_510500_security_id(str(selected["contract"])),
        "quote": selected,
        "expiry": expiry,
        "strike": float(selected["strike"]),
        "qty": qty,
        "iv": iv,
        "absolute_delta": absolute_delta,
        "stamp": stamp,
    }


def _mo_enriched(quotes: pd.DataFrame, option_type: str, today: date) -> pd.DataFrame:
    pattern = rf"MO(\d{{2}})(\d{{2}})-{option_type}-(\d+)"
    rows = quotes[quotes["instrument"].str.fullmatch(pattern)].copy()
    parsed = rows["instrument"].str.extract(pattern)
    rows["expiry"] = [
        _third_friday(2000 + int(year), int(month))
        for year, month in zip(parsed[0], parsed[1], strict=True)
    ]
    rows["strike"] = pd.to_numeric(parsed[2], errors="coerce")
    return rows[rows["expiry"].gt(today)].copy()


def _listed_mo_enriched(
    quotes: pd.DataFrame,
    option_type: str,
    today: date,
) -> pd.DataFrame:
    """Parse the raw listed set without pretending no-trade rows are executable."""

    instruments = quotes.attrs.get("listed_instruments")
    if not instruments:
        instruments = quotes["instrument"].tolist()
    raw = pd.DataFrame({"instrument": sorted(set(map(str, instruments)))})
    pattern = rf"MO(\d{{2}})(\d{{2}})-{option_type}-(\d+)"
    raw = raw[raw["instrument"].str.fullmatch(pattern)].copy()
    if raw.empty:
        return raw.assign(expiry=pd.Series(dtype=object), strike=pd.Series(dtype=float))
    parsed = raw["instrument"].str.extract(pattern)
    raw["expiry"] = [
        _third_friday(2000 + int(year), int(month))
        for year, month in zip(parsed[0], parsed[1], strict=True)
    ]
    raw["strike"] = pd.to_numeric(parsed[2], errors="coerce")
    return raw[raw["expiry"].gt(today)].copy()


def select_im_put_for_reset(
    quotes: pd.DataFrame, today: date, spot: float
) -> pd.Series:
    listed_puts = _listed_mo_enriched(quotes, "P", today)
    target_day = (pd.Timestamp(today) + pd.DateOffset(months=3)).date()
    expiries = sorted(set(listed_puts["expiry"]))
    if not expiries:
        raise RuntimeError("没有未来MO Put挂牌月份")
    expiry = min(expiries, key=lambda value: (abs((value - target_day).days), value))
    listed_month = listed_puts[listed_puts["expiry"].eq(expiry)].copy()
    listed_month["strike_error"] = (listed_month["strike"] - 0.95 * spot).abs()
    selected_contract = str(
        listed_month.sort_values(["strike_error", "instrument"]).iloc[0]["instrument"]
    )
    puts = _mo_enriched(quotes, "P", today)
    eligible = puts[
        puts["instrument"].eq(selected_contract)
        & puts["lastprice"].gt(0)
        & puts["volume"].gt(0)
        & puts["position"].gt(0)
    ].copy()
    if eligible.empty:
        raise RuntimeError(
            f"MO规则目标Put {selected_contract} 已挂牌但缺少可执行报价，禁止跳月或跳行权价"
        )
    return eligible.iloc[0]


def _independent_im_put_target_expiry(
    quotes: pd.DataFrame, today: date
) -> date:
    """Match the independent replay's 3m listed-month choice, including ties."""

    listed_puts = _listed_mo_enriched(quotes, "P", today)
    target_day = (pd.Timestamp(today) + pd.DateOffset(months=3)).date()
    expiries = sorted(set(listed_puts["expiry"]))
    if not expiries:
        raise RuntimeError("没有未来MO Put挂牌月份")
    # Historical independent replay chooses the later actual expiry on a tie.
    return min(expiries, key=lambda value: (abs((value - target_day).days), -value.toordinal()))


def select_independent_im_put_for_reset(
    quotes: pd.DataFrame, today: date, spot: float
) -> pd.Series:
    """Select a fresh independent-sleeve Put with replay-identical month semantics."""

    expiry = _independent_im_put_target_expiry(quotes, today)
    listed_puts = _listed_mo_enriched(quotes, "P", today)
    listed_month = listed_puts[listed_puts["expiry"].eq(expiry)].copy()
    listed_month["strike_error"] = (listed_month["strike"] - 0.95 * spot).abs()
    selected_contract = str(
        listed_month.sort_values(["strike_error", "instrument"]).iloc[0]["instrument"]
    )
    puts = _mo_enriched(quotes, "P", today)
    eligible = puts[
        puts["instrument"].eq(selected_contract)
        & puts["lastprice"].gt(0)
        & puts["volume"].gt(0)
        & puts["position"].gt(0)
    ].copy()
    if eligible.empty:
        raise RuntimeError(
            f"MO动量Put规则目标 {selected_contract} 已挂牌但缺少可执行报价，禁止跳月或跳行权价"
        )
    return eligible.iloc[0]


def select_im_call_d10(
    quotes: pd.DataFrame, today: date, spot: float, anchor_expiry: date
) -> dict[str, Any] | None:
    listed_calls = _listed_mo_enriched(quotes, "C", today)
    listed_expiries = sorted(
        set(listed_calls.loc[listed_calls["expiry"].gt(anchor_expiry), "expiry"])
    )
    if not listed_expiries:
        return None
    expiry = listed_expiries[0]
    calls = _mo_enriched(quotes, "C", today)
    calls = calls[
        calls["expiry"].eq(expiry)
        & calls["strike"].gt(spot)
        & calls["lastprice"].gt(0)
        & calls["volume"].gt(0)
        & calls["position"].gt(0)
    ].copy()
    if calls.empty:
        return None
    selections: list[dict[str, Any]] = []
    for row in calls.itertuples(index=False):
        years = max((expiry - today).days, 1) / 365.0
        iv = _implied_volatility(
            "C",
            float(row.lastprice),
            spot,
            float(row.strike),
            float(FROZEN["IM"]["gov10y"]),
            float(FROZEN["IM"]["dividend"]),
            years,
        )
        if iv is None:
            continue
        delta = _bs_price_delta(
            "C",
            spot,
            float(row.strike),
            float(FROZEN["IM"]["gov10y"]),
            float(FROZEN["IM"]["dividend"]),
            iv,
            years,
        )[1]
        selections.append(
            {
                "row": pd.Series(row._asdict()),
                "iv": iv,
                "delta": delta,
                "expiry": expiry,
            }
        )
    if not selections:
        return None
    return min(
        selections,
        key=lambda item: (abs(item["delta"] - 0.10), -float(item["row"]["position"])),
    )


def select_im_call_rescue(
    quotes: pd.DataFrame,
    today: date,
    spot: float,
    old_expiry: date,
    old_strike: float,
) -> dict[str, Any] | None:
    listed_calls = _listed_mo_enriched(quotes, "C", today)
    listed_expiries = sorted(
        set(listed_calls.loc[listed_calls["expiry"].gt(old_expiry), "expiry"])
    )
    if not listed_expiries:
        return None
    expiry = listed_expiries[0]
    listed_expiry = listed_calls[
        listed_calls["expiry"].eq(expiry)
        & listed_calls["strike"].ge(old_strike * 1.05 - 1e-12)
    ].sort_values(["strike", "instrument"])
    if listed_expiry.empty:
        return None
    target_contract = str(listed_expiry.iloc[0]["instrument"])
    calls = _mo_enriched(quotes, "C", today)
    calls = calls[
        calls["instrument"].eq(target_contract)
        & calls["lastprice"].gt(0)
        & calls["volume"].gt(0)
        & calls["position"].gt(0)
    ].copy()
    if calls.empty:
        return None
    row = calls.iloc[0]
    years = max((expiry - today).days, 1) / 365.0
    iv = _implied_volatility(
        "C",
        float(row["lastprice"]),
        spot,
        float(row["strike"]),
        float(FROZEN["IM"]["gov10y"]),
        float(FROZEN["IM"]["dividend"]),
        years,
    )
    if iv is None:
        return None
    delta = _bs_price_delta(
        "C",
        spot,
        float(row["strike"]),
        float(FROZEN["IM"]["gov10y"]),
        float(FROZEN["IM"]["dividend"]),
        iv,
        years,
    )[1]
    return {"row": row, "iv": iv, "delta": delta, "expiry": expiry}


def _market_phase(clock: datetime) -> str:
    if not _is_exchange_trading_day(clock.date()):
        return "非交易日"
    current = clock.time()
    if time(9, 30) <= current < time(11, 30) or time(13, 0) <= current < time(15, 0):
        return "盘中"
    if time(9, 25) <= current < time(9, 30):
        return "集合竞价"
    if current >= time(15, 0):
        return "收盘后"
    if current < time(9, 25):
        return "开盘前"
    return "午间休市"


def _is_pre_expiry_close(today: date, active_expiry: date, phase: str) -> bool:
    next_trading_day = _roll_forward_exchange_day(today + timedelta(days=1))
    return next_trading_day == active_expiry and phase in {"收盘后", "非交易日"}


def _calendar_coverage_note(expiries: Iterable[date]) -> str | None:
    uncovered_years = sorted(
        {day.year for day in expiries if day.year not in _OFFICIAL_EXCHANGE_CALENDAR_YEARS}
    )
    if not uncovered_years:
        return None
    years = "/".join(str(year) for year in uncovered_years)
    return (
        f"挂牌合约包含{years}年到期日，但脚本尚未载入该年度官方休市表；"
        "这些到期日暂按周一至周五回退，须在交易所发布年度休市安排后更新"
    )


def _validate_market_stamp(label: str, value: str, clock: datetime) -> date:
    cleaned = str(value).strip()
    try:
        stamp_day = (
            datetime.strptime(cleaned, "%Y%m%d").date()
            if re.fullmatch(r"\d{8}", cleaned)
            else date.fromisoformat(cleaned)
        )
    except ValueError as exc:
        raise RuntimeError(f"{label}缺少可验证的行情日期") from exc
    expected = _latest_completed_exchange_day(clock)
    if stamp_day > clock.date():
        raise RuntimeError(f"{label}行情日期 {stamp_day} 晚于北京时间 {clock.date()}")
    if stamp_day < expected:
        raise RuntimeError(
            f"{label}行情已过期：最新 {stamp_day}，至少应覆盖 {expected}；暂停生成信号"
        )
    return stamp_day


def _validate_chain_stamp_matches(
    label: str,
    stamp: dict[str, str],
    reference_day: date,
    clock: datetime,
) -> date:
    chain_day = _validate_market_stamp(label, stamp.get("date", ""), clock)
    if chain_day != reference_day:
        raise RuntimeError(
            f"{label}与参考行情日期不一致：{chain_day} != {reference_day}"
        )
    return chain_day


def _require_intraday_bridge_source_day(
    label: str,
    source_day: Any,
    market_date: date,
    enabled: bool,
) -> None:
    if not enabled:
        return
    try:
        parsed = (
            source_day
            if isinstance(source_day, date) and not isinstance(source_day, datetime)
            else date.fromisoformat(str(source_day)[:10])
        )
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"{label}缺少{market_date}当日可验证行情日期") from exc
    if parsed != market_date:
        raise RuntimeError(
            f"{label}桥接行情日期为 {parsed}，必须等于当日 {market_date}；暂停新增信号"
        )


def _next_unverified_session_bridge_allowed(
    product: str,
    market_date: date,
    clock: datetime,
    mode: str,
) -> bool:
    verified_day = LIVE_CONTINUATION_ANCHOR[product]["last_verified_day"]
    next_day = _roll_forward_exchange_day(verified_day + timedelta(days=1))
    phase = _market_phase(clock)
    if mode == "intraday":
        allowed_phases = {"集合竞价", "盘中", "午间休市", "收盘后"}
    else:
        allowed_phases = {"收盘后"}
    expected_completed_day = _latest_completed_exchange_day(clock)
    same_session = market_date == clock.date() and phase in allowed_phases
    completed_session_replay = (
        market_date < clock.date() and expected_completed_day == market_date
    )
    return (
        market_date == next_day
        and (same_session or completed_session_replay)
        and expected_completed_day in {verified_day, market_date}
    )


def _validate_signal_market_date(
    product: str,
    market_date: date,
    clock: datetime,
    mode: str = "close",
) -> bool:
    if market_date > clock.date():
        raise RuntimeError(
            f"{product} 行情日期 {market_date} 晚于北京时间 {clock.date()}"
        )
    expected = _latest_completed_exchange_day(clock)
    if market_date < expected:
        raise RuntimeError(
            f"{product} 行情已过期：最新 {market_date}，至少应覆盖最近已完成交易日 "
            f"{expected}；暂停新增信号"
        )
    verified_day = LIVE_CONTINUATION_ANCHOR[product]["last_verified_day"]
    if market_date > verified_day:
        if _next_unverified_session_bridge_allowed(
            product, market_date, clock, mode
        ):
            return True
        raise RuntimeError(
            f"{product} 审计账本仅逐腿核验至 {verified_day}，尚未可靠重放 "
            f"{market_date} 的期货、Put及Call状态；暂停新增信号"
        )
    return False


def _apply_next_unverified_session_anchor(
    product: str,
    live: dict[str, Any],
) -> dict[str, Any]:
    anchor = LIVE_CONTINUATION_ANCHOR[product]
    result = dict(live)
    # Momentum and grid close signals execute at the next session open.  During
    # the first unverified session the current position is therefore the
    # audited close target, not the position that existed before that close.
    result["momentum_current_weight"] = float(
        anchor.get("verified_next_momentum_weight", anchor["verified_momentum_weight"])
    )
    result["momentum_current_source_date"] = anchor["last_verified_day"]
    result["grid_current_units"] = float(
        anchor.get("verified_next_grid_units", anchor["verified_grid_units"])
    )
    result["state_anchor_day"] = anchor["last_verified_day"]
    if product == "IC":
        result["v13_current_core_put_delta"] = float(
            anchor["verified_core_put_delta"]
        )
        result["v13_current_momentum_put_delta"] = float(
            anchor["verified_momentum_put_delta"]
        )
        result["v13_current_put_delta"] = float(
            anchor["verified_total_put_delta"]
        )
        result["current_core_put_driver"] = anchor["verified_core_put_driver"]
        result["current_momentum_put_driver"] = anchor[
            "verified_momentum_put_driver"
        ]
    else:
        result["v13_current_parent_puts"] = int(anchor["verified_parent_puts"])
        result["v13_current_put_qty_normalized"] = float(
            anchor["verified_core_put_qty_normalized"]
        )
        result["v13_current_core_put_qty_normalized"] = float(
            anchor["verified_core_put_qty_normalized"]
        )
        result["v13_current_momentum_put_qty_normalized"] = float(
            anchor["verified_momentum_put_qty_normalized"]
        )
        result["v13_current_total_put_qty_normalized"] = float(
            anchor["verified_total_put_qty_normalized"]
        )
    return result


def _validated_signal_state_anchor_day(
    product: str,
    live: dict[str, Any],
    bridge_from_anchor: bool,
) -> date | None:
    value = live.get("state_anchor_day")
    if isinstance(value, pd.Timestamp):
        value = value.date()
    elif value is not None and not isinstance(value, date):
        value = date.fromisoformat(str(value)[:10])
    if not bridge_from_anchor:
        return value
    expected = LIVE_CONTINUATION_ANCHOR[product]["last_verified_day"]
    if value != expected:
        raise RuntimeError(
            f"{product}账本桥接状态锚点不一致：期望 {expected}，实际 {value}"
        )
    return value


def build_live_trade_signal(
    product: str,
    now: datetime | None = None,
    mode: str = "intraday",
) -> dict[str, Any]:
    if mode not in {"intraday", "close"}:
        raise ValueError(f"非法信号模式: {mode}")
    clock = now or _now_beijing()
    _require_official_exchange_calendar(clock.date(), f"{product}信号")
    today = clock.date()
    live = live_proxy(product, clock)
    market_date = live.get("history_date", today)
    if isinstance(market_date, pd.Timestamp):
        market_date = market_date.date()
    if not isinstance(market_date, date):
        market_date = date.fromisoformat(str(market_date))
    bridge_from_anchor = _validate_signal_market_date(
        product, market_date, clock, mode
    )
    if bridge_from_anchor:
        live = _apply_next_unverified_session_anchor(product, live)
    state_anchor_day = _validated_signal_state_anchor_day(
        product, live, bridge_from_anchor
    )
    future_quotes = fetch_cffex_quotes(product, clock)
    future_quote_source = str(future_quotes.attrs.get("source", "未知"))
    future_quote_date = future_quotes.attrs.get("source_date")
    _require_intraday_bridge_source_day(
        f"{product}期货", future_quote_date, market_date, bridge_from_anchor
    )
    # Contract state is determined by the market/as-of day.  Using the wall
    # clock here would let a weekend query skip an unpriced strict next month
    # and jump directly to a quarterly contract.
    active_future = select_active_future(product, future_quotes, market_date)
    active_expiry = _third_friday(*_contract_month(str(active_future["instrument"])))
    phase = _market_phase(clock)
    later_futures = future_quotes[
        future_quotes["instrument"].str.fullmatch(rf"{product}\d{{4}}")
    ].copy()
    later_futures["expiry"] = later_futures["instrument"].map(
        lambda value: _third_friday(*_contract_month(value))
    )
    calendar_note = _calendar_coverage_note(later_futures["expiry"])
    later_futures = later_futures[
        later_futures["expiry"].gt(active_expiry)
    ].sort_values("expiry")
    next_core = _next_listed_future_contract(
        product, future_quotes, active_expiry
    )
    pre_expiry_close = _is_pre_expiry_close(market_date, active_expiry, phase)
    roll_signal_due = active_expiry == market_date or pre_expiry_close
    roll_execution_date = active_expiry if roll_signal_due else None
    if roll_signal_due:
        if not next_core:
            raise RuntimeError(f"{product}月换时没有更晚的实际挂牌期货合约")
        active_future = _require_listed_future_quote(
            product, later_futures, next_core
        )
    ledger_core = str(LIVE_CONTINUATION_ANCHOR[product]["post_core_contract"])
    target_core = str(active_future["instrument"])
    ledger_core_expiry = _third_friday(*_contract_month(ledger_core))
    scheduled_roll_completed = market_date >= ledger_core_expiry
    current_core = ledger_core
    if roll_signal_due:
        core_action = "ROLL"
    elif target_core != current_core:
        raise RuntimeError(
            f"{product} 行情活跃合约 {target_core} 与已核验账本当前合约"
            f" {current_core} 不一致，暂停生成信号"
        )
    else:
        core_action = "HOLD"
    grid_units, grid_action = _grid_target(product, live)
    close_confirmed = market_date < today or (
        market_date == today and phase in {"收盘后", "非交易日"}
    )
    if mode == "intraday":
        stage = (
            "盘中实时监测，须待T收盘确认"
            if phase == "盘中"
            else f"{phase}，返回最新可得行情"
        )
    elif close_confirmed:
        stage = f"最近已完成交易日 {market_date} 的收盘信号"
    else:
        stage = f"{market_date} 尚未收盘，收盘信号未形成"
    data_notes = [
        "本次请求重新抓取中金所/上交所/指数行情",
        "估值与MOM120为当前价格代理",
        f"{product}期货源：{future_quote_source}，as-of {future_quote_date}",
    ]
    if product == "IM":
        data_notes.append(
            f"中证1000 OHLCV源：{live.get('momentum_ohlcv_source', '未知')}；"
            + (
                "盘中成交量使用已确认状态占位，不把不可验证累计量写入信号"
                if live.get("momentum_volume_placeholder")
                else "成交量已通过日期、OHLC关系、正值与数量级校验"
            )
        )
    if bridge_from_anchor:
        data_notes.append(
            f"账本下一交易日桥接：当前腿固定取"
            f"{LIVE_CONTINUATION_ANCHOR[product]['last_verified_day']}已核验收盘锚点；"
            f"{market_date}行情只形成下一交易日目标"
        )
    data_notes.extend(future_quotes.attrs.get("source_audit", []))
    if future_quotes.attrs.get("source_failures"):
        data_notes.append(
            "行情源回退/不可用汇总："
            + "；".join(future_quotes.attrs["source_failures"])
        )
    if calendar_note:
        data_notes.append(calendar_note)
    signal: dict[str, Any] = {
        "product": product,
        "mode": mode,
        "market_phase": phase,
        "market_date": market_date,
        "close_confirmed": close_confirmed,
        "state_anchor_day": state_anchor_day,
        "stage": stage,
        "fetch_time": clock.strftime("%Y-%m-%d %H:%M:%S"),
        "index_price": live["price"],
        "score": live["score"],
        "momentum_120": live["momentum_120"],
        "momentum_score": live["momentum_score"],
        "momentum_abs20": live["momentum_abs20"],
        "momentum_volume_ratio": live["momentum_volume_ratio"],
        "momentum_volume_pass": live["momentum_volume_pass"],
        "momentum_volume_placeholder": live["momentum_volume_placeholder"],
        "momentum_score_hot": live["momentum_score_hot"],
        "momentum_base_nav": live["momentum_base_nav"],
        "momentum_base_dd": live["momentum_base_dd"],
        "momentum_nav_defense": live["momentum_nav_defense"],
        "momentum_ohlcv_source": live["momentum_ohlcv_source"],
        "momentum_current_weight": live["momentum_current_weight"],
        "momentum_next_weight": live["momentum_next_weight"],
        "momentum_signal_date": live["momentum_signal_date"],
        "momentum_current_source_date": live["momentum_current_source_date"],
        "next_trade_date": _roll_forward_exchange_day(
            market_date + timedelta(days=1)
        ),
        "core_current": current_core,
        "core_target": target_core,
        "core_action": core_action,
        "future_last": float(active_future["lastprice"]),
        "future_bid": float(active_future.get("bprice", np.nan)),
        "future_ask": float(active_future.get("sprice", np.nan)),
        "future_quote_source": future_quote_source,
        "future_quote_date": future_quote_date,
        "future_expiry": _third_friday(*_contract_month(target_core)),
        "next_core": next_core,
        "roll_date": active_expiry,
        "roll_execution_date": roll_execution_date,
        "scheduled_roll_completed": scheduled_roll_completed,
        "grid_current": int(round(float(live["grid_current_units"]))),
        "grid_target": grid_units,
        "grid_action": grid_action,
        "data_notes": data_notes,
    }

    if product == "IC":
        put_contract = str(LIVE_CONTINUATION_ANCHOR["IC"]["post_put_contract"])
        match = re.search(r"P(\d{4})", put_contract)
        if not match:
            raise RuntimeError(f"无法解析IC Put合约: {put_contract}")
        replay_day = _HISTORICAL_REPLAY_DAY.get()
        if replay_day is not None:
            security_id = LIVE_CONTINUATION_ANCHOR["IC"].get(
                "post_put_security_id"
            )
            if not security_id:
                raise RuntimeError(
                    f"IC历史补账缺少既有Put {put_contract} 的证券代码映射"
                )
            chain, sse_stamp = fetch_sse_existing_put_historical_quote(
                put_contract, str(security_id), replay_day
            )
            etf = fetch_sse_510500_historical_quote(replay_day)
        else:
            chain, sse_stamp = fetch_sse_510500_chain(match.group(1))
            etf = fetch_sse_510500_quote()
        chain_day = _validate_market_stamp("上交所510500期权链", sse_stamp["date"], clock)
        etf_day = _validate_market_stamp("上交所510500ETF", etf["date"], clock)
        _require_intraday_bridge_source_day(
            "上交所510500期权链", chain_day, market_date, bridge_from_anchor
        )
        _require_intraday_bridge_source_day(
            "上交所510500ETF", etf_day, market_date, bridge_from_anchor
        )
        if chain_day != etf_day:
            raise RuntimeError(
                f"上交所ETF与期权链日期不一致：{etf_day} != {chain_day}"
            )
        put_quote = _quote_row(chain, put_contract)
        target_delta = float(live["v13_put_target_delta"])
        prior_delta = float(live["v13_current_put_delta"])
        current_core_delta = float(live["v13_current_core_put_delta"])
        current_momentum_delta = float(live["v13_current_momentum_put_delta"])
        target_core_delta = float(live["v13_core_put_delta"])
        target_momentum_delta = float(live["v13_momentum_put_delta"])
        put_current = (
            f"组合目标绝对Delta {prior_delta:.1%}，账本合约 {put_contract}"
        )
        put_target = (
            "无需Put，绝对Delta 0%"
            if math.isclose(target_delta, 0.0, rel_tol=0.0, abs_tol=1e-12)
            else f"绝对Delta {target_delta:.0%}，沿用 {put_contract}"
        )
        put_action = (
            "HOLD"
            if math.isclose(target_delta, prior_delta) and core_action == "HOLD"
            else "RESIZE_OR_ROLL"
        )
        _require_existing_leg_quote("IC Put", put_contract, put_quote, put_action)
        put_market = _format_market(put_contract, put_quote)
        put_target_contract_value: str | None = put_contract
        put_target_security_id_value: str | None = str(
            LIVE_CONTINUATION_ANCHOR["IC"].get("post_put_security_id") or ""
        ) or None
        ic_sizing: dict[str, Any] = {}
        if replay_day is not None and core_action == "ROLL":
            raise RuntimeError(
                "IC历史补账遇到月换日，缺少该日完整510500期权链归档；禁止用当前链替代"
            )
        if core_action == "HOLD":
            anchored_total = int(LIVE_CONTINUATION_ANCHOR["IC"]["post_put_qty"])
            protection_changed = not (
                math.isclose(target_delta, prior_delta, abs_tol=1e-12)
                and math.isclose(target_core_delta, current_core_delta, abs_tol=1e-12)
                and math.isclose(
                    target_momentum_delta, current_momentum_delta, abs_tol=1e-12
                )
            )
            if protection_changed:
                if put_quote is None:
                    raise RuntimeError(
                        f"IC既有Put {put_contract} 无有效行情，禁止账本续接"
                    )
                ic_sizing = _size_existing_ic_put(
                    put_contract,
                    put_quote,
                    market_date,
                    float(etf["last"]),
                    float(active_future["lastprice"]),
                    anchored_total,
                    current_core_delta,
                    current_momentum_delta,
                    target_core_delta,
                    target_momentum_delta,
                )
                ic_sizing["put_selection_note"] = (
                    f"{LIVE_CONTINUATION_ANCHOR['IC']['last_verified_day']}已核验账本续接；"
                    "保护档变化，沿用既有合约并按当日有效价格重算IV/Delta后调整张数"
                )
            else:
                core_share = (
                    current_core_delta / prior_delta if prior_delta > 0 else 0.0
                )
                anchored_core = int(round(anchored_total * core_share))
                anchored_momentum = anchored_total - anchored_core
                ic_sizing = {
                    "put_current_total_qty": anchored_total,
                    "put_current_core_qty": anchored_core,
                    "put_current_momentum_qty": anchored_momentum,
                    "put_current_grid_qty": 0,
                    "put_target_total_qty": anchored_total,
                    "put_target_core_qty": anchored_core,
                    "put_target_momentum_qty": anchored_momentum,
                    "put_target_grid_qty": 0,
                    "put_selection_note": (
                        f"{LIVE_CONTINUATION_ANCHOR['IC']['last_verified_day']}已核验账本续接；"
                        "保护档未变，沿用既有合约与张数"
                    ),
                }
            anchored_core = int(ic_sizing["put_current_core_qty"])
            anchored_momentum = int(ic_sizing["put_current_momentum_qty"])
            target_total = int(ic_sizing["put_target_total_qty"])
            target_core_qty = int(ic_sizing["put_target_core_qty"])
            target_momentum = int(ic_sizing["put_target_momentum_qty"])
            put_current = (
                f"共{anchored_total}张（裸滚核心袖{anchored_core}张 + "
                f"动量指引袖{anchored_momentum}张 + 网格0张） {put_contract}"
            )
            put_target = (
                "无需Put，绝对Delta 0%"
                if target_total == 0
                else (
                    f"共{target_total}张（裸滚核心袖{target_core_qty}张 + "
                    f"动量指引袖{target_momentum}张 + 网格0张） {put_contract}"
                )
            )
        elif core_action == "ROLL" or scheduled_roll_completed:
            reset_day = (
                frozen_core_expiry
                if scheduled_roll_completed
                else (roll_execution_date or today)
            )
            reset = select_ic_put_for_reset(
                reset_day,
                float(etf["last"]),
                float(active_future["lastprice"]),
                target_delta,
            )
            put_target_contract_value = (
                str(reset["contract"]) if reset["contract"] else None
            )
            put_target_security_id_value = (
                str(reset.get("security_id")) if reset.get("security_id") else None
            )
            if reset["stamp"] is not None:
                _validate_chain_stamp_matches(
                    "上交所510500新月份期权链",
                    reset["stamp"],
                    etf_day,
                    clock,
                )
            if reset["qty"] == 0:
                put_target = "无需Put，绝对Delta 0%"
                put_market = "无（目标Delta为0%）"
            else:
                qty_text = (
                    f"多 {reset['qty']}张"
                    if reset["qty"] is not None
                    else "数量待有效IV"
                )
                put_target = (
                    f"每1倍组合规模规范化{qty_text} {reset['contract']}，"
                    f"绝对Delta {target_delta:.1%}"
                )
                put_market = _format_market(str(reset["contract"]), reset["quote"])
                if reset["absolute_delta"] is not None:
                    future_notional = float(active_future["lastprice"]) * 200.0
                    etf_option_notional = float(etf["last"]) * 10_000.0
                    full_equivalent = max(
                        1, round(future_notional / etf_option_notional)
                    )
                    raw_qty = (
                        full_equivalent
                        * target_delta
                        / float(reset["absolute_delta"])
                    )
                    current_breakdown = _ic_put_quantity_breakdown(
                        full_equivalent,
                        float(reset["absolute_delta"]),
                        current_core_delta,
                        current_momentum_delta,
                    )
                    target_breakdown = _ic_put_quantity_breakdown(
                        full_equivalent,
                        float(reset["absolute_delta"]),
                        target_core_delta,
                        target_momentum_delta,
                        int(reset["qty"]),
                    )
                    ic_sizing = {
                        "put_sizing_future_price": float(active_future["lastprice"]),
                        "put_sizing_future_multiplier": 200,
                        "put_sizing_future_notional": future_notional,
                        "put_sizing_etf_price": float(etf["last"]),
                        "put_sizing_option_multiplier": 10_000,
                        "put_sizing_etf_option_notional": etf_option_notional,
                        "put_sizing_full_equivalent_contracts": full_equivalent,
                        "put_sizing_target_delta": target_delta,
                        "put_sizing_option_abs_delta": float(reset["absolute_delta"]),
                        "put_sizing_raw_qty": raw_qty,
                        "put_sizing_rounded_qty": int(reset["qty"]),
                        "put_current_total_qty": int(current_breakdown["total"]),
                        "put_current_core_qty": int(current_breakdown["core"]),
                        "put_current_momentum_qty": int(
                            current_breakdown["momentum"]
                        ),
                        "put_current_grid_qty": 0,
                        "put_target_total_qty": int(target_breakdown["total"]),
                        "put_target_core_qty": int(target_breakdown["core"]),
                        "put_target_momentum_qty": int(
                            target_breakdown["momentum"]
                        ),
                        "put_target_grid_qty": 0,
                        "put_sizing_iv": reset["iv"],
                        "put_sizing_expiry": reset["expiry"],
                        "put_sizing_strike": reset["strike"],
                        "put_sizing_signal_date": reset_day,
                        "put_sizing_target_expiry_date": (
                            pd.Timestamp(reset_day) + pd.DateOffset(months=3)
                        ).date(),
                    }
                    put_current = (
                        f"共{current_breakdown['total']}张（裸滚核心袖"
                        f"{current_breakdown['core']}张 + 动量指引袖"
                        f"{current_breakdown['momentum']}张 + 网格0张） "
                        f"{reset['contract']}"
                    )
                    put_target = (
                        f"共{target_breakdown['total']}张（裸滚核心袖"
                        f"{target_breakdown['core']}张 + 动量指引袖"
                        f"{target_breakdown['momentum']}张 + 网格0张） "
                        f"{reset['contract']}"
                    )
                if scheduled_roll_completed:
                    if not ic_sizing:
                        put_current = f"规则续接合约 {reset['contract']}"
        put_action = (
            "HOLD"
            if math.isclose(target_delta, prior_delta, abs_tol=1e-12)
            and core_action == "HOLD"
            else "RESIZE_OR_ROLL"
        )
        signal.update(
            {
                "etf_price": etf["last"],
                "sse_time": f"{sse_stamp['date']} {sse_stamp['time']}",
                "put_current": put_current,
                "put_target": put_target,
                "put_action": put_action,
                "put_market": put_market,
                "call_current": "无",
                "call_target": "无（IC 1.3明确禁止Call）",
                "call_action": "HOLD",
                "put_current_contract": put_contract,
                "put_target_contract": put_target_contract_value,
                "put_target_security_id": put_target_security_id_value,
                "call_current_contract": None,
                "call_target_contract": None,
                "call_target_qty_normalized": 0.0,
                "core_put_target_delta": live["v13_core_put_delta"],
                "momentum_put_target_delta": live["v13_momentum_put_delta"],
                "total_put_target_delta": live["v13_put_target_delta"],
                "core_put_current_delta": live["v13_current_core_put_delta"],
                "momentum_put_current_delta": live[
                    "v13_current_momentum_put_delta"
                ],
                "total_put_current_delta": live["v13_current_put_delta"],
                "valuation_tier": live["valuation_tier"],
                "valuation_tier_label": live["valuation_tier_label"],
                "valuation_put_delta": live["valuation_put_delta"],
                "mom120_floor_delta": live["mom120_floor_delta"],
                "current_core_put_driver": live["current_core_put_driver"],
                "current_momentum_put_driver": live[
                    "current_momentum_put_driver"
                ],
                "core_put_driver": live["core_put_driver"],
                "momentum_put_driver": live["momentum_put_driver"],
                **ic_sizing,
            }
        )
    else:
        mo_quotes = fetch_cffex_quotes("MO", clock)
        mo_quote_source = str(mo_quotes.attrs.get("source", "未知"))
        mo_quote_date = mo_quotes.attrs.get("source_date")
        _require_intraday_bridge_source_day(
            "MO期权链", mo_quote_date, market_date, bridge_from_anchor
        )
        data_notes.append(f"MO期权链源：{mo_quote_source}，as-of {mo_quote_date}")
        data_notes.extend(mo_quotes.attrs.get("source_audit", []))
        if mo_quotes.attrs.get("source_failures"):
            data_notes.append(
                "MO行情源回退/不可用汇总："
                + "；".join(mo_quotes.attrs["source_failures"])
            )
        option_rows_to_verify: dict[str, float] = {}
        im_anchor = LIVE_CONTINUATION_ANCHOR["IM"]
        core_put_contract = str(
            im_anchor.get("post_core_put_contract") or im_anchor["post_put_contract"]
        )
        core_put_quote = _quote_row(mo_quotes, core_put_contract)
        momentum_put_contract_value = im_anchor.get("post_momentum_put_contract")
        momentum_put_contract = (
            str(momentum_put_contract_value)
            if momentum_put_contract_value not in (None, "")
            else None
        )
        momentum_put_quote = (
            _quote_row(mo_quotes, momentum_put_contract)
            if momentum_put_contract
            else None
        )
        put_target = int(live["v13_parent_puts_per_full_core"])
        prior_put = int(live["v13_current_parent_puts"])
        core_put_target_normalized = float(live["v13_put_target_qty_normalized"])
        core_put_current_normalized = float(
            im_anchor["verified_core_put_qty_normalized"]
        )
        momentum_put_current_normalized = float(
            im_anchor["verified_momentum_put_qty_normalized"]
        )
        momentum_put_target_normalized = (
            core_put_target_normalized * float(live["momentum_next_weight"])
        )
        total_put_current_normalized = (
            core_put_current_normalized + momentum_put_current_normalized
        )
        total_put_target_normalized = (
            core_put_target_normalized + momentum_put_target_normalized
        )
        core_put_target_contract = core_put_contract
        core_put_target_text = (
            "无需Put（目标0张）"
            if put_target == 0
            else (
                f"0.5倍核心袖规范化多 {core_put_target_normalized:g}张 "
                f"{core_put_target_contract}（父规则每1倍 {put_target}张）"
            )
        )
        core_put_market = _format_market(core_put_contract, core_put_quote)
        im_contract_selection: dict[str, Any] = {}
        if core_action == "HOLD":
            im_contract_selection["put_selection_note"] = (
                f"{LIVE_CONTINUATION_ANCHOR['IM']['last_verified_day']}已核验账本续接；"
                "非月换日沿用既有合约，只按保护档调整张数"
            )
        elif (core_action == "ROLL" or scheduled_roll_completed) and put_target > 0:
            reset_day = (
                ledger_core_expiry
                if scheduled_roll_completed
                else (roll_execution_date or today)
            )
            selected_put = select_im_put_for_reset(
                mo_quotes, reset_day, float(live["price"])
            )
            core_put_target_contract = str(selected_put["instrument"])
            core_put_target_text = (
                f"0.5倍核心袖规范化多 {core_put_target_normalized:g}张 "
                f"{core_put_target_contract}（父规则每1倍 {put_target}张）"
            )
            core_put_market = _format_market(core_put_target_contract, selected_put)
            option_rows_to_verify[core_put_target_contract] = float(
                selected_put["lastprice"]
            )
            im_contract_selection = {
                "put_sizing_expiry": selected_put["expiry"],
                "put_sizing_strike": float(selected_put["strike"]),
                "put_sizing_signal_date": reset_day,
                "put_sizing_target_expiry_date": (
                    pd.Timestamp(reset_day) + pd.DateOffset(months=3)
                ).date(),
                "put_sizing_target_strike": 0.95 * float(live["price"]),
            }

        momentum_put_target_contract: str | None = None
        momentum_put_target_quote: pd.Series | None = None
        momentum_put_selection_note = "动量执行权重为0，目标空仓"
        if momentum_put_target_normalized > 0.0:
            desired_expiry = _independent_im_put_target_expiry(
                mo_quotes, market_date
            )
            current_expiry = (
                _third_friday(*_contract_month(momentum_put_contract))
                if momentum_put_contract
                else None
            )
            if momentum_put_contract and current_expiry == desired_expiry:
                momentum_put_target_contract = momentum_put_contract
                momentum_put_target_quote = momentum_put_quote
                momentum_put_selection_note = (
                    "独立动量Put目标月份未变，沿用既有动量腿合约并只调整数量"
                )
            else:
                selected_momentum_put = select_independent_im_put_for_reset(
                    mo_quotes, market_date, float(live["price"])
                )
                if selected_momentum_put["expiry"] != desired_expiry:
                    raise RuntimeError("IM动量Put独立期限选择与真实重放规则不一致")
                momentum_put_target_contract = str(
                    selected_momentum_put["instrument"]
                )
                momentum_put_target_quote = selected_momentum_put
                option_rows_to_verify[momentum_put_target_contract] = float(
                    selected_momentum_put["lastprice"]
                )
                momentum_put_selection_note = (
                    "动量Put由零进入或目标月份变化，按当日IM收盘独立选择约3个月、95%行权价"
                )
        momentum_put_current_text = (
            "独立动量Put 0张"
            if momentum_put_current_normalized == 0.0
            else f"独立动量Put {momentum_put_current_normalized:g}张 {momentum_put_contract}"
        )
        momentum_put_target_text = (
            "独立动量Put 0张"
            if momentum_put_target_normalized == 0.0
            else f"独立动量Put {momentum_put_target_normalized:g}张 {momentum_put_target_contract}"
        )
        call_contract_value = LIVE_CONTINUATION_ANCHOR["IM"].get(
            "verified_call_contract"
        )
        call_expiry_value = LIVE_CONTINUATION_ANCHOR["IM"].get(
            "verified_call_expiry"
        )
        call_strike_value = LIVE_CONTINUATION_ANCHOR["IM"].get(
            "verified_call_strike"
        )
        call_contract = (
            str(call_contract_value) if call_contract_value not in (None, "") else None
        )
        call_quote = _quote_row(mo_quotes, call_contract) if call_contract else None
        call_expiry = (
            date.fromisoformat(str(call_expiry_value)) if call_expiry_value else None
        )
        call_otm = (
            float(call_strike_value) / float(live["price"]) - 1.0
            if call_strike_value is not None
            else np.nan
        )
        call_market = (
            _format_market(call_contract, call_quote)
            if call_contract
            else "无（已核验Call仓位为0）"
        )
        call_finished = call_contract is None or (
            call_expiry is not None
            and (
                today > call_expiry
                or (today == call_expiry and clock.time() >= time(15, 0))
            )
        )
        threat_roll_count = int(
            LIVE_CONTINUATION_ANCHOR["IM"].get("verified_threat_roll_count", 0)
            
        )
        call_target_contract: str | None = None
        call_target_expiry: date | None = None
        call_target_strike: float | None = None
        call_target_qty_normalized = 0.0
        call_target_threat_roll_count = threat_roll_count
        if not call_finished:
            if call_otm <= 0.05 + 1e-12:
                if threat_roll_count >= 5:
                    call_action = "CLOSE_CALL"
                    call_target = "买回旧Call并暂停；已达到连续5次救援上限"
                else:
                    rescue = select_im_call_rescue(
                        mo_quotes,
                        today,
                        float(live["price"]),
                        call_expiry,
                        float(call_strike_value),
                    )
                    if rescue is None:
                        call_action = "CLOSE_CALL"
                        call_target = (
                            "买回旧Call；没有符合rescue_next_listed与行权价上移5%的合约"
                        )
                    else:
                        call_action = "RESCUE_NEXT_LISTED"
                        rescue_row = rescue["row"]
                        call_target_contract = str(rescue_row["instrument"])
                        call_target_expiry = rescue["expiry"]
                        call_target_strike = float(rescue_row["strike"])
                        call_target_qty_normalized = -1.0
                        call_target_threat_roll_count = threat_roll_count + 1
                        call_target = (
                            f"买回旧Call并空2张 {rescue_row['instrument']}（rescue_next_listed，"
                            f"Delta {rescue['delta']:.3f}，IV {rescue['iv']:.2%}，救援豁免IV26%）"
                        )
                        call_market = _format_market(
                            str(rescue_row["instrument"]), rescue_row
                        )
                        option_rows_to_verify[str(rescue_row["instrument"])] = float(
                            rescue_row["lastprice"]
                        )
            else:
                call_action = "HOLD"
                call_target_contract = call_contract
                call_target_expiry = call_expiry
                call_target_strike = (
                    float(call_strike_value) if call_strike_value is not None else None
                )
                call_target_qty_normalized = -1.0
                call_target = f"空2张 {call_contract}"
        else:
            selected_call = select_im_call_d10(
                mo_quotes,
                today,
                float(live["price"]),
                _third_friday(*_contract_month(target_core)),
            )
            if selected_call is None:
                call_action = "WAIT_IV_OR_CHAIN"
                call_target = "旧Call已到期；未找到有效D10候选，保持空仓"
            elif float(selected_call["iv"]) >= 0.26:
                call_action = "OPEN_CALL"
                selected_row = selected_call["row"]
                call_target_contract = str(selected_row["instrument"])
                call_target_expiry = selected_call["expiry"]
                call_target_strike = float(selected_row["strike"])
                call_target_qty_normalized = -1.0
                call_target_threat_roll_count = 0
                call_target = (
                    f"空2张 {selected_row['instrument']}（Delta {selected_call['delta']:.3f}，"
                    f"IV {selected_call['iv']:.2%}）"
                )
                call_market = _format_market(
                    str(selected_row["instrument"]), selected_row
                )
                option_rows_to_verify[str(selected_row["instrument"])] = float(
                    selected_row["lastprice"]
                )
            else:
                call_action = "WAIT_IV"
                selected_row = selected_call["row"]
                call_target = f"D10候选 {selected_row['instrument']} 的IV {selected_call['iv']:.2%}<26%，保持空仓"
                call_market = _format_market(
                    str(selected_row["instrument"]), selected_row
                )
                option_rows_to_verify[str(selected_row["instrument"])] = float(
                    selected_row["lastprice"]
                )
        if call_contract:
            _require_existing_leg_quote("IM Call", call_contract, call_quote, call_action)
        core_put_action = (
            "HOLD"
            if math.isclose(
                core_put_target_normalized,
                core_put_current_normalized,
                abs_tol=1e-12,
            )
            and core_put_target_contract == core_put_contract
            and core_action == "HOLD"
            else "RESIZE_OR_ROLL"
        )
        momentum_put_action = (
            "HOLD"
            if math.isclose(
                momentum_put_target_normalized,
                momentum_put_current_normalized,
                abs_tol=1e-12,
            )
            and momentum_put_target_contract == momentum_put_contract
            else "RESIZE_OR_ROLL"
        )
        im_put_action = (
            "HOLD"
            if core_put_action == "HOLD" and momentum_put_action == "HOLD"
            else "RESIZE_OR_ROLL"
        )
        if core_put_current_normalized > 0.0:
            _require_existing_leg_quote(
                "IM核心Put", core_put_contract, core_put_quote, core_put_action
            )
        if momentum_put_current_normalized > 0.0:
            if momentum_put_contract is None:
                raise RuntimeError("IM动量Put账本数量非零但合约为空，拒绝继续")
            _require_existing_leg_quote(
                "IM动量Put",
                momentum_put_contract,
                momentum_put_quote,
                momentum_put_action,
            )
        if mo_quote_source == "东方财富":
            for contract, price in option_rows_to_verify.items():
                verification = verify_sina_option_quote(
                    contract,
                    mo_quote_date,
                    price,
                    clock,
                )
                data_notes.append(
                    f"{contract}经{verification['source']}复核，as-of "
                    f"{verification['source_date']}，最新{verification['lastprice']:g}"
                )
        call_current_text = (
            "规范化0张（已核验空仓，等待新D10/IV26信号）"
            if call_contract is None
            else (
                "0张（旧Call已到期，等待新D10信号）"
                if call_finished
                else f"规范化空1张 {call_contract}（只覆盖0.5倍核心袖）"
            )
        )
        call_target = call_target.replace("空2张", "规范化空1张")
        put_current_text = (
            f"核心Put {core_put_current_normalized:g}张 {core_put_contract}；"
            f"{momentum_put_current_text}；合计 {total_put_current_normalized:g}张"
        )
        put_target_text = (
            f"{core_put_target_text}；{momentum_put_target_text}；"
            f"合计 {total_put_target_normalized:g}张"
        )
        momentum_put_market = (
            "无（目标与当前均为空仓）"
            if momentum_put_contract is None
            and momentum_put_target_contract is None
            else _format_market(
                momentum_put_target_contract or momentum_put_contract,
                (
                    momentum_put_target_quote
                    if momentum_put_target_quote is not None
                    else momentum_put_quote
                ),
            )
        )
        put_market = f"核心：{core_put_market}；动量：{momentum_put_market}"
        signal.update(
            {
                "put_current": put_current_text,
                "put_target": put_target_text,
                "put_action": im_put_action,
                "put_market": put_market,
                "put_current_contract": core_put_contract,
                "put_target_contract": (
                    core_put_target_contract if put_target > 0 else None
                ),
                "core_put_current_contract": core_put_contract,
                "core_put_target_contract": (
                    core_put_target_contract if put_target > 0 else None
                ),
                "momentum_put_current_contract": momentum_put_contract,
                "momentum_put_target_contract": momentum_put_target_contract,
                "call_current": call_current_text,
                "call_target": call_target,
                "call_action": call_action,
                "call_market": call_market,
                "call_current_contract": call_contract,
                "call_target_contract": call_target_contract,
                "call_target_expiry": call_target_expiry,
                "call_target_strike": call_target_strike,
                "call_target_qty_normalized": call_target_qty_normalized,
                "call_target_threat_roll_count": call_target_threat_roll_count,
                "call_otm": call_otm,
                "call_expiry": call_expiry,
                "call_has_position": call_contract is not None and not call_finished,
                "threat_roll_count": threat_roll_count,
                "core_put_target_qty_normalized": core_put_target_normalized,
                "core_put_current_qty_normalized": core_put_current_normalized,
                "v13_parent_puts_per_full_core": put_target,
                "v13_current_parent_puts_per_full_core": prior_put,
                "momentum_put_target_qty_normalized": momentum_put_target_normalized,
                "momentum_put_current_qty_normalized": momentum_put_current_normalized,
                "total_put_target_qty_normalized": total_put_target_normalized,
                "total_put_current_qty_normalized": total_put_current_normalized,
                "core_put_action": core_put_action,
                "momentum_put_action": momentum_put_action,
                "momentum_put_selection_note": momentum_put_selection_note,
                "absolute_valuation_tier": live["absolute_valuation_tier"],
                "absolute_valuation_tier_label": live[
                    "absolute_valuation_tier_label"
                ],
                "relative_valuation_tier": live["relative_valuation_tier"],
                "relative_valuation_tier_label": live[
                    "relative_valuation_tier_label"
                ],
                "valuation_puts_per_full_core": live[
                    "valuation_puts_per_full_core"
                ],
                "mom120_floor_puts_per_full_core": live[
                    "mom120_floor_puts_per_full_core"
                ],
                "core_put_driver": live["core_put_driver"],
                **im_contract_selection,
            }
        )
    current_momentum_units = 0.5 * float(signal["momentum_current_weight"])
    target_momentum_units = 0.5 * float(signal["momentum_next_weight"])
    current_total_units = 0.5 + current_momentum_units + float(signal["grid_current"])
    target_total_units = 0.5 + target_momentum_units + float(signal["grid_target"])
    momentum_change = target_momentum_units - current_momentum_units
    signal.update(
        {
            "core_units_current": 0.5,
            "core_units_target": 0.5,
            "momentum_units_current": current_momentum_units,
            "momentum_units_target": target_momentum_units,
            "momentum_units_change": momentum_change,
            "momentum_action": (
                "HOLD"
                if math.isclose(momentum_change, 0.0, abs_tol=1e-12)
                else ("INCREASE" if momentum_change > 0 else "DECREASE")
            ),
            "total_units_current": current_total_units,
            "total_units_target": target_total_units,
            "total_units_change": target_total_units - current_total_units,
        }
    )
    return signal


def _sm() -> Any:
    return poe.start_message()


def _write_last_verified_snapshot(msg: Any, product: str) -> None:
    anchor = LIVE_CONTINUATION_ANCHOR[product]
    momentum_weight = float(anchor["verified_momentum_weight"])
    grid_units = float(anchor["verified_grid_units"])
    total_units = 0.5 + 0.5 * momentum_weight + grid_units
    put_qty = float(anchor["verified_put_qty_normalized"])
    put_contract = str(anchor["post_put_contract"])
    call_qty = float(anchor["verified_call_contracts_normalized"])
    call_text = "无（IC禁止Call）" if product == "IC" else f"规范化 {call_qty:g}张"
    if product == "IM":
        core_put_qty = float(anchor["verified_core_put_qty_normalized"])
        momentum_put_qty = float(anchor["verified_momentum_put_qty_normalized"])
        core_put_contract = str(anchor["post_core_put_contract"])
        momentum_contract = anchor.get("post_momentum_put_contract")
        momentum_text = (
            "0张"
            if momentum_put_qty == 0.0
            else f"{momentum_put_qty:g}张 `{momentum_contract}`"
        )
        put_snapshot = (
            f"核心 {core_put_qty:g}张 `{core_put_contract}`；"
            f"动量 {momentum_text}；合计 {put_qty:g}张"
        )
    else:
        put_snapshot = f"{put_qty:g}张 `{put_contract}`"
    msg.write(
        f"**最后逐腿核验快照（{anchor['last_verified_day']}，仅研究审计）**\n\n"
        f"- 0.5倍核心袖：`{anchor['post_core_contract']}`\n"
        f"- 动量袖：权重 {momentum_weight:g}，期货名义 {0.5 * momentum_weight:g}倍\n"
        f"- 独立网格：{grid_units:g}倍；期货合计：{total_units:g}倍\n"
        f"- Put：{put_snapshot}；Call：{call_text}\n"
        "- 这只是最后已核验状态，不是当前账户持仓；联网或账本续接恢复前，"
        "不生成下一交易日目标。\n\n"
    )


