    def _handle_performance(self, intent: QueryIntent) -> None:
        assert intent.start is not None and intent.end is not None
        with _sm() as msg:
            msg.write(
                f"## 1.3 历史表现：{intent.start} 至 {intent.end}\n\n"
            )
            request_deadline = (
                time_module.monotonic() + PERFORMANCE_NETWORK_BUDGET_SECONDS
            )
            for product in intent.products:
                degraded_reason: str | None = None
                try:
                    remaining = max(0.25, request_deadline - time_module.monotonic())
                    with _network_budget(remaining):
                        frame = performance_frame(
                            product, intent.start, intent.end, refresh_latest=True
                        )
                except (
                    ValueError,
                    RuntimeError,
                    requests.RequestException,
                    zipfile.BadZipFile,
                    KeyError,
                ) as exc:
                    if intent.end > DATA_CUTOFF:
                        try:
                            frame = performance_frame(
                                product,
                                intent.start,
                                min(intent.end, DATA_CUTOFF),
                                refresh_latest=False,
                            )
                            degraded_reason = f"{type(exc).__name__}: {exc}"
                        except (ValueError, RuntimeError, KeyError) as fallback_exc:
                            msg.write(
                                f"### {product}\n\n⚠️ 联网续接失败，冻结历史也无法覆盖所选区间："
                                f"{fallback_exc}\n\n"
                            )
                            continue
                    else:
                        msg.write(f"### {product}\n\n⚠️ {exc}\n\n")
                        continue
                metrics = performance_metrics(frame)
                actual_end = frame.index[-1].date()
                live_rows = int(frame["is_live"].sum())
                transition_rows = int(frame["is_transition"].sum())
                chart = render_nav_drawdown_chart(product, frame, intent.start)
                msg.write(f"### {PRODUCT_NAMES[product]}\n\n")
                if degraded_reason is not None:
                    msg.write(
                        f"⚠️ 联网续接失败，已明确降级到哈希校验的冻结历史终点 "
                        f"**{actual_end}**；未外推、未伪造后续收益。原因："
                        f"`{degraded_reason}`\n\n"
                    )
                benchmark_cn = "中证500价格指数" if product == "IC" else "中证1000价格指数"
                msg.attach_file(
                    name=f"{product.lower()}_nav_drawdown_{intent.start}_{actual_end}.png",
                    contents=chart,
                    content_type="image/png",
                    is_inline=True,
                )
                if live_rows:
                    msg.write(
                        f"数据已更新至 **{actual_end}**：{DATA_CUTOFF}及以前为1.3哈希校验定值参考段，"
                        f"其后 {live_rows} 个交易日按真实期货、期权和指数日行情实时续接。"
                        "历史段不会被改写。\n\n"
                    )
                    if transition_rows:
                        transition_note = (
                            "；IM旧Call到期归零" if product == "IM" else ""
                        )
                        msg.write(
                            "续接已包含 **2026-08-21** 月换日：当日按旧仓盯市，"
                            f"收盘计入期货展期、Put重置及相应交易成本{transition_note}。\n\n"
                        )
                else:
                    msg.write(f"本次区间数据截至 **{actual_end}**。\n\n")
                if actual_end < intent.end:
                    msg.write(
                        f"请求终点晚于当前可核验终点；{actual_end}之后暂无已纳入且完成"
                        "逐腿核验的交易日收益，未用假设仓位外推。\n\n"
                    )
                msg.write(
                    f"区间收益 **{metrics['return']:.2%}**｜年化 **{metrics['cagr']:.2%}**｜"
                    f"年化波动 **{metrics['volatility']:.2%}**｜夏普 **{metrics['sharpe']:.2f}**｜"
                    f"最大回撤 **{metrics['max_drawdown']:.2%}**\n\n"
                )
                msg.write(
                    f"净值图已叠加 **{benchmark_cn}** 收盘价格曲线；两条曲线均按查询区间首日归一为1。\n\n"
                )
            msg.write(
                "绩效口径：IC按1.3 NAV防守后的新动量权重重跑期货成本、Put成交与现金，再叠加独立网格；IM为0.5倍核心+0.5倍1.3动量，"
                "核心与动量分别持有独立Put，Call仍只覆盖核心袖，并叠加1.60/2.00独立网格。每1倍期货按30%保证金/缓冲、"
                "剩余现金3%；未另行加入滑点、冲击、涨跌停未成交、容量、动态保证金上调和税费。\n\n"
                "2015年至期权上市前包含理论/代理段；本结果是只读研究参考，不是实盘授权。\n\n"
            )
            if "IM" in intent.products:
                msg.write(
                    "特别披露：IM上市前模型段保留既有 **10.32%年化基差** 定值参考；"
                    "该数值来自上市后真实样本回填，含未来信息，只能用于参考曲线，"
                    "不得解释为样本外绩效或实盘依据。\n\n"
                )


